# --------------------------- basic io / logging ---------------------------

def _log(prefix: str, msg: str) -> None:
    print(f'[{prefix}] {msg}')


def log_info(msg: str) -> None:
    _log('INFO', msg)


def log_ok(msg: str) -> None:
    _log('OK', msg)


def log_warn(msg: str) -> None:
    _log('WARN', msg)


def load_json(path: Path) -> Any:
    with path.open('r', encoding='utf-8') as f:
        return json.load(f)


def _deep_merge(base: dict[str, Any], overlay: dict[str, Any]) -> dict[str, Any]:
    out = copy.deepcopy(base)
    for key, value in overlay.items():
        if isinstance(value, dict) and isinstance(out.get(key), dict):
            out[key] = _deep_merge(out[key], value)
        else:
            out[key] = copy.deepcopy(value)
    return out


def _load_background_profile(exp: dict[str, Any], config_path: Path) -> dict[str, Any]:
    raw = exp.get('background_profile_path')
    if not isinstance(raw, str) or not raw.strip():
        return exp
    profile_path = _resolve_input_path(raw, config_path=config_path)
    profile = load_json(profile_path)
    if not isinstance(profile, dict) or profile.get('schema_version') not in {'background_profile_v1', 'background_profile_v2'}:
        raise ValueError(f'Invalid background profile: {profile_path}')
    out = copy.deepcopy(exp)
    manifest_raw = profile.get('manifest')
    if not isinstance(manifest_raw, str):
        raise ValueError(f'Background profile lacks manifest: {profile_path}')
    out['manifest'] = str(_resolve_input_path(manifest_raw, config_path=profile_path))
    anchor = out.get('background_anchor', profile.get('default_background_anchor', [0, 0, 0]))
    if not (isinstance(anchor, (list, tuple)) and len(anchor) >= 3):
        raise ValueError('background_anchor must contain x, y, z')
    anchor = [float(anchor[0]), float(anchor[1]), float(anchor[2])]
    profile_scene = copy.deepcopy(profile.get('scene_overrides', {}))
    local_lights = profile_scene.pop('raytracing_lights_local', None)
    if isinstance(local_lights, list):
        lights = []
        for light in local_lights:
            item = copy.deepcopy(light)
            pos = item.get('pos')
            if isinstance(pos, (list, tuple)) and len(pos) >= 3:
                item['pos'] = tuple(float(pos[i]) + anchor[i] for i in range(3))
            lights.append(item)
        profile_scene['raytracing_lights'] = lights
    # The selected background owns its visual lighting; physics fields absent
    # from the profile (gravity, dt, solver settings) stay untouched.
    out['scene_overrides'] = _deep_merge(out.get('scene_overrides', {}), profile_scene)
    out['render'] = _deep_merge(out.get('render', {}), profile.get('render_defaults', {}))
    out['background_profile_id'] = profile['background_profile_id']
    out['_background_anchor'] = anchor
    metadata = copy.deepcopy(out.get('sample_metadata', {}))
    metadata.update({
        'background_profile_id': profile['background_profile_id'],
        'background_profile_path': str(profile_path),
        'background_geometry_sha256': profile.get('geometry_sha256'),
        'background_anchor': anchor,
        'background_license': profile.get('license'),
    })
    out['sample_metadata'] = metadata
    log_info(f'Loaded background profile: {profile["background_profile_id"]} anchor={anchor}')
    return out


def _translate_background_manifest(manifest: dict[str, Any], anchor: list[float] | None) -> dict[str, Any]:
    if not anchor or all(abs(float(x)) < 1e-12 for x in anchor):
        return manifest
    out = copy.deepcopy(manifest)
    for obj in out.get('objects', []):
        if not isinstance(obj, dict):
            continue
        pose = obj.setdefault('pose', {})
        pos = pose.get('position', [0, 0, 0])
        if isinstance(pos, (list, tuple)) and len(pos) >= 3:
            pose['position'] = [float(pos[i]) + float(anchor[i]) for i in range(3)]
    layout = out.get('layout')
    if isinstance(layout, dict):
        pose = layout.setdefault('pose', {})
        pos = pose.get('position', [0, 0, 0])
        if isinstance(pos, (list, tuple)) and len(pos) >= 3:
            pose['position'] = [float(pos[i]) + float(anchor[i]) for i in range(3)]
    return out


def save_json(path: Path, data: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(data, indent=2, ensure_ascii=False), encoding='utf-8')


def safe_makedirs(path: Path | str) -> Path:
    p = Path(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    return p


# --------------------------- dynamic imports ---------------------------

def _load_module(path: Path, name: str) -> Any:
    spec = importlib.util.spec_from_file_location(name, path)
    if spec is None or spec.loader is None:
        raise RuntimeError(f'Failed to load module from {path}')
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


