# --------------------------- scene building ---------------------------

def _build_scene_with_overrides(stage06: Any, show_viewer: bool, scene_cfg: dict[str, Any]) -> Any:
    gs = stage06.gs
    kwargs: dict[str, Any] = {'show_viewer': show_viewer}
    if bool(scene_cfg.get('raytracing', scene_cfg.get('use_raytracing', False))):
        rt_kwargs: dict[str, Any] = {
            'logging_level': str(scene_cfg.get('raytracing_logging_level', 'warning')),
            'state_limit': int(scene_cfg.get('raytracing_state_limit', 2**25)),
            'tracing_depth': int(scene_cfg.get('raytracing_depth', 8)),
            'rr_depth': int(scene_cfg.get('raytracing_rr_depth', 2)),
            'lights': scene_cfg.get(
                'raytracing_lights',
                [],
            ),
            'env_radius': float(scene_cfg.get('raytracing_env_radius', 20.0)),
        }
        env_color = scene_cfg.get('raytracing_env_color', [0.035, 0.038, 0.042])
        env_map = scene_cfg.get('raytracing_env_map')
        env_required = bool(scene_cfg.get('raytracing_env_map_required', False))
        if isinstance(env_map, str) and env_map.strip():
            try:
                env_path = Path(env_map)
                if not env_path.exists():
                    raise FileNotFoundError(env_path)
                encoding = str(scene_cfg.get('raytracing_env_encoding', 'linear'))
                texture = gs.textures.ImageTexture(image_path=str(env_path), encoding=encoding)
                rt_kwargs['env_surface'] = gs.surfaces.Emission(emissive_texture=texture)
                rt_kwargs['env_euler'] = tuple(float(x) for x in scene_cfg.get('raytracing_env_euler', [0, 0, 0]))
                gain = scene_cfg.get('raytracing_env_gain_baked', 1.0)
                log_info(f'RayTracer environment map: {env_path} encoding={encoding} baked_gain={gain}')
            except Exception as exc:
                if env_required:
                    raise RuntimeError(f'Required RayTracer environment map failed: {env_map}: {exc}') from exc
                log_warn(f'Environment map unavailable, using color fallback: {exc}')
        if 'env_surface' not in rt_kwargs and hasattr(gs, 'surfaces') and hasattr(gs.surfaces, 'Emission') and hasattr(gs, 'textures') and hasattr(gs.textures, 'ColorTexture'):
            rt_kwargs['env_surface'] = gs.surfaces.Emission(
                emissive_texture=gs.textures.ColorTexture(color=tuple(float(x) for x in env_color[:3]))
            )
        try:
            kwargs['renderer'] = gs.renderers.RayTracer(**rt_kwargs)
        except Exception as exc:
            log_warn(f'RayTracer renderer requested but unavailable; falling back to default renderer: {exc}')
    if hasattr(gs, 'options') and hasattr(gs.options, 'SimOptions'):
        sim_kwargs: dict[str, Any] = {}
        if 'dt' in scene_cfg:
            sim_kwargs['dt'] = float(scene_cfg['dt'])
        if 'substeps' in scene_cfg:
            sim_kwargs['substeps'] = int(scene_cfg['substeps'])
        gravity = scene_cfg.get('gravity')
        if isinstance(gravity, (list, tuple)) and len(gravity) >= 3:
            sim_kwargs['gravity'] = (float(gravity[0]), float(gravity[1]), float(gravity[2]))
        try:
            kwargs['sim_options'] = gs.options.SimOptions(**sim_kwargs)
        except Exception:
            fallback = {k: v for k, v in sim_kwargs.items() if k in ('dt', 'substeps')}
            kwargs['sim_options'] = gs.options.SimOptions(**fallback)
    # GJK is slower than the legacy MPR path, but is substantially more stable
    # for fast, thin tabletop mesh contacts. Keep it opt-in so older datasets
    # retain their original solver behavior.
    if hasattr(gs, 'options') and hasattr(gs.options, 'RigidOptions'):
        rigid_kwargs: dict[str, Any] = {}
        for key in (
            'use_gjk_collision', 'enable_multi_contact', 'box_box_detection',
            'use_contact_island',
            'iterations', 'ls_iterations', 'noslip_iterations',
            'tolerance', 'ls_tolerance', 'noslip_tolerance',
            'constraint_timeconst', 'contact_resolve_time', 'max_collision_pairs',
        ):
            if key in scene_cfg:
                rigid_kwargs[key] = scene_cfg[key]
        if rigid_kwargs:
            try:
                kwargs['rigid_options'] = gs.options.RigidOptions(**rigid_kwargs)
            except Exception as exc:
                log_warn(f'RigidOptions overrides unavailable; using defaults: {exc}')
    try:
        return gs.Scene(**kwargs)
    except Exception:
        return gs.Scene()


def _to_vec3(values: Any, default: tuple[float, float, float]) -> tuple[float, float, float]:
    if isinstance(values, (list, tuple)) and len(values) >= 3:
        try:
            return (float(values[0]), float(values[1]), float(values[2]))
        except Exception:
            return default
    return default


def _read_scene_gravity(scene: Any) -> tuple[float, float, float] | None:
    probes = [scene, getattr(scene, 'sim', None), getattr(scene, 'rigid_solver', None)]
    for obj in probes:
        if obj is None:
            continue
        for name in ('get_gravity', 'gravity'):
            if not hasattr(obj, name):
                continue
            try:
                value = getattr(obj, name)
                out = value() if callable(value) else value
                if hasattr(out, 'detach'):
                    out = out.detach().cpu().numpy()
                arr = np.asarray(out, dtype=float).reshape(-1)
                if arr.size >= 3:
                    return (float(arr[0]), float(arr[1]), float(arr[2]))
            except Exception:
                continue
    return None


def _apply_scene_gravity(scene: Any, gravity: Any) -> list[str]:
    if not (isinstance(gravity, (list, tuple)) and len(gravity) >= 3):
        return []
    g = (float(gravity[0]), float(gravity[1]), float(gravity[2]))
    probes = [scene, getattr(scene, 'sim', None), getattr(scene, 'rigid_solver', None)]
    applied: list[str] = []
    for obj in probes:
        if obj is None:
            continue
        if not hasattr(obj, 'set_gravity'):
            continue
        fn = getattr(obj, 'set_gravity')
        try:
            fn(g)
            applied.append(f'{obj.__class__.__name__}.set_gravity')
            continue
        except Exception:
            pass
        try:
            fn(*g)
            applied.append(f'{obj.__class__.__name__}.set_gravity')
        except Exception:
            continue
    return applied


def _pick_mesh_path(obj: dict[str, Any]) -> str | None:
    for key in ('mesh_path', 'resolved_mesh'):
        value = obj.get(key)
        if isinstance(value, str) and value.strip():
            return value
    chain = obj.get('material_chain', {})
    if isinstance(chain, dict):
        value = chain.get('mesh_path')
        if isinstance(value, str) and value.strip():
            return value
    return None




def _pick_collision_mesh_path(obj: dict[str, Any]) -> str | None:
    for key in ('collision_mesh_path', 'collision_mesh', 'proxy_mesh_path'):
        value = obj.get(key)
        if isinstance(value, str) and value.strip():
            return value
    return None

def _extract_room_bounds_hint(manifest: dict[str, Any]) -> dict[str, Any] | None:
    layout = manifest.get('layout', {})
    if isinstance(layout, dict):
        for key in ('room_bounds', 'bounds'):
            value = layout.get(key)
            if isinstance(value, dict):
                return value
    return None


def _room_bounds_from_context(manifest: dict[str, Any], placement_debug: dict[str, Any] | None, layout_mesh: str | None, scene_cfg: dict[str, Any]) -> dict[str, list[float]] | None:
    raw = scene_cfg.get('room_bounds')
    if isinstance(raw, dict):
        value = raw
    elif isinstance(placement_debug, dict) and isinstance(placement_debug.get('room_bounds'), dict):
        value = placement_debug['room_bounds']
    else:
        try:
            placement_utils = _load_placement_utils()
            value = placement_utils.estimate_room_bounds(layout_mesh, _extract_room_bounds_hint(manifest))
        except Exception:
            value = None
    if not isinstance(value, dict):
        return None
    try:
        bmin = value.get('min')
        bmax = value.get('max')
        if not (isinstance(bmin, (list, tuple)) and isinstance(bmax, (list, tuple)) and len(bmin) >= 3 and len(bmax) >= 3):
            return None
        return {
            'min': [float(bmin[0]), float(bmin[1]), float(bmin[2])],
            'max': [float(bmax[0]), float(bmax[1]), float(bmax[2])],
        }
    except Exception:
        return None


def _room_wall_collider_specs(bounds: dict[str, list[float]] | None, scene_cfg: dict[str, Any]) -> list[dict[str, Any]]:
    wall_cfg = scene_cfg.get('room_wall_colliders', {})
    if wall_cfg is False or (isinstance(wall_cfg, dict) and wall_cfg.get('enabled') is False):
        return []
    if not isinstance(bounds, dict):
        return []
    cfg = wall_cfg if isinstance(wall_cfg, dict) else {}
    thickness = max(0.05, float(cfg.get('thickness', 0.18)))
    restitution = float(cfg.get('restitution', 0.72))
    friction = float(cfg.get('friction', 0.38))
    zmin = float(bounds['min'][2])
    zmax = float(bounds['max'][2])
    height = max(0.5, zmax - zmin)
    xmin, ymin = float(bounds['min'][0]), float(bounds['min'][1])
    xmax, ymax = float(bounds['max'][0]), float(bounds['max'][1])
    xmid = 0.5 * (xmin + xmax)
    ymid = 0.5 * (ymin + ymax)
    xlen = max(0.5, xmax - xmin)
    ylen = max(0.5, ymax - ymin)
    zc = zmin + 0.5 * height
    color = [0.82, 0.80, 0.74]

    def wall(name: str, pos: list[float], size: list[float]) -> dict[str, Any]:
        return {
            'name': name,
            'shape': 'box',
            'fixed': True,
            'collision': True,
            'size': [float(size[0]), float(size[1]), float(size[2])],
            'color': color,
            'mass': 0.0,
            'friction': friction,
            'restitution': restitution,
            'material_type': 'wall_collider',
            'camera_focus': False,
            'pose': {'position': [float(pos[0]), float(pos[1]), float(pos[2])], 'euler_xyz': [0.0, 0.0, 0.0]},
            'motion': {'type': 'none'},
            'is_room_wall_collider': True,
        }

    return [
        wall('room_wall_xmin_collider', [xmin - thickness * 0.5, ymid, zc], [thickness, ylen + 2.0 * thickness, height]),
        wall('room_wall_xmax_collider', [xmax + thickness * 0.5, ymid, zc], [thickness, ylen + 2.0 * thickness, height]),
        wall('room_wall_ymin_collider', [xmid, ymin - thickness * 0.5, zc], [xlen + 2.0 * thickness, thickness, height]),
        wall('room_wall_ymax_collider', [xmid, ymax + thickness * 0.5, zc], [xlen + 2.0 * thickness, thickness, height]),
    ]


def _load_and_adjust_static_objects(manifest: dict[str, Any], cfg: dict[str, Any]) -> tuple[list[dict[str, Any]], dict[str, Any], str | None]:
    placement_utils = _load_placement_utils()
    objects = manifest.get('objects', [])
    if not isinstance(objects, list):
        objects = []
    layout = manifest.get('layout', {})
    layout_mesh = layout.get('mesh_path') if isinstance(layout, dict) else None

    if cfg.get('skip_placement', False):
        placement_debug = {
            'placement_skipped': True,
            'summary': {'object_count': len(objects)},
            'objects': [],
        }
        return [obj for obj in objects if isinstance(obj, dict)], placement_debug, layout_mesh

    pcfg = placement_utils.default_placement_config()
    m_cfg = manifest.get('placement_defaults', {})
    if isinstance(m_cfg, dict):
        pcfg.update(m_cfg)
    for k in ('floor_margin', 'boundary_margin', 'collision_margin', 'max_attempts', 'step_size'):
        if k in cfg and cfg[k] is not None:
            pcfg[k] = cfg[k]
    pcfg = placement_utils.normalize_placement_config(pcfg)

    adjusted_objects, placement_debug = placement_utils.validate_and_resolve_placements(
        [obj for obj in objects if isinstance(obj, dict)],
        layout_mesh_path=layout_mesh,
        room_bounds=_extract_room_bounds_hint(manifest),
        config=pcfg,
    )
    return adjusted_objects, placement_debug, layout_mesh


def _add_ground_plane(stage06: Any, scene: Any, scene_cfg: dict[str, Any]) -> None:
    """Add the physical ground with a versioned realistic visual surface."""
    if not bool(scene_cfg.get('add_ground_plane', True)):
        log_info('Ground plane disabled: experiment supplies its own explicit support collider.')
        return
    gs = stage06.gs
    spec = scene_cfg.get('ground_surface')
    if not isinstance(spec, dict):
        stage06._add_plane(scene)
        return
    color_raw = spec.get('color', [0.48, 0.47, 0.44, 1.0])
    color = tuple(float(x) for x in color_raw[:4])
    if len(color) == 3:
        color = (*color, 1.0)
    surface_kwargs: dict[str, Any] = {
        'color': color,
        'roughness': float(spec.get('roughness', 0.78)),
        'metallic': float(spec.get('metallic', 0.0)),
    }
    texture_fields = {
        'diffuse_texture': ('basecolor_path', 'srgb'),
        'roughness_texture': ('roughness_path', 'linear'),
        'metallic_texture': ('metallic_path', 'linear'),
        'normal_texture': ('normal_path', 'linear'),
    }
    for surface_key, (path_key, encoding) in texture_fields.items():
        raw = spec.get(path_key)
        if not isinstance(raw, str) or not Path(raw).exists():
            continue
        try:
            surface_kwargs[surface_key] = gs.textures.ImageTexture(image_path=raw, encoding=encoding)
        except Exception as exc:
            log_warn(f'Ground {surface_key} unavailable: {exc}')
    # Genesis 0.4.1 treats scalar/color fields as texture shortcuts and rejects
    # setting both representations for the same channel.
    if 'diffuse_texture' in surface_kwargs:
        surface_kwargs.pop('color', None)
    try:
        surface = gs.surfaces.Rough(**surface_kwargs)
        plane_size = tuple(float(x) for x in spec.get('plane_size', [30.0, 30.0])[:2])
        tile_size = tuple(float(x) for x in spec.get('tile_size', [1.5, 1.5])[:2])
        morph = gs.morphs.Plane(pos=(0.0, 0.0, float(spec.get('z', 0.0))), plane_size=plane_size, tile_size=tile_size)
        scene.add_entity(morph=morph, material=gs.materials.Rigid(), surface=surface)
        log_info(f'Added realistic ground surface: {spec.get("profile_id", "custom")}')
    except Exception as exc:
        log_warn(f'Realistic ground surface failed, using default plane: {exc}')
        stage06._add_plane(scene)


def _add_static_scene(stage06: Any, scene: Any, manifest: dict[str, Any], adjusted_objects: list[dict[str, Any]], layout_mesh: str | None, use_full_scene: bool, scene_cfg: dict[str, Any]) -> dict[str, Any]:
    placement_utils = _load_placement_utils()
    static_entities: dict[str, Any] = {}
    _add_ground_plane(stage06, scene, scene_cfg)
    layout = manifest.get('layout', {})
    layout_collision = bool(scene_cfg.get('layout_collision', True))
    static_scene_collision = bool(scene_cfg.get('static_scene_collision', True))
    visual_only_ids = {
        str(value).strip()
        for value in scene_cfg.get('static_visual_only_instance_ids', [])
        if str(value).strip()
    }

    full_scene_loaded = False
    if use_full_scene:
        full_scene_mesh = manifest.get('full_scene_mesh_path')
        if not isinstance(full_scene_mesh, str):
            full_scene_mesh = layout.get('full_scene_mesh_path') if isinstance(layout, dict) else None
        if isinstance(full_scene_mesh, str) and Path(full_scene_mesh).exists():
            try:
                morph, _ = stage06._mesh_morph(Path(full_scene_mesh), fixed=True, pose=None)
                stage06._add_entity(scene, morph)
                full_scene_loaded = True
                log_info(f'Loaded full scene mesh: {full_scene_mesh}')
            except Exception as exc:
                log_warn(f'Failed to load full scene mesh {full_scene_mesh}: {exc}')

    if not full_scene_loaded and isinstance(layout_mesh, str) and Path(layout_mesh).exists():
        layout_pose = layout.get('pose') if isinstance(layout, dict) and isinstance(layout.get('pose'), dict) else None
        morph, layout_kwargs = stage06._mesh_morph(
            Path(layout_mesh),
            fixed=True,
            pose=layout_pose,
            visualization=True,
            collision=layout_collision,
        )
        layout_entity = stage06._add_entity(scene, morph)
        if layout_pose is not None and not stage06._mesh_kwargs_has_pose(layout_kwargs):
            stage06._apply_entity_pose(layout_entity, layout_pose)
        log_info(f'Loaded layout mesh: {layout_mesh} | collision={layout_collision}')

    for obj in adjusted_objects:
        iid = str(obj.get('instance_id', 'unknown'))
        is_proxy = bool(obj.get('is_proxy', False))
        mesh_path = _pick_mesh_path(obj)
        pose = placement_utils.extract_pose(obj)

        collision_mesh_path = _pick_collision_mesh_path(obj)
        if not static_scene_collision or iid in visual_only_ids:
            if not is_proxy and isinstance(mesh_path, str) and Path(mesh_path).exists():
                try:
                    visual_morph, visual_kwargs = stage06._mesh_morph(
                        Path(mesh_path), fixed=True, pose=pose, visualization=True, collision=False
                    )
                    visual_ent = stage06._add_entity(scene, visual_morph)
                    if not stage06._mesh_kwargs_has_pose(visual_kwargs):
                        stage06._apply_entity_pose(visual_ent, pose)
                    static_entities[iid] = visual_ent
                    reason = 'static_scene_collision_disabled' if not static_scene_collision else 'instance_override'
                    log_info(f'[binding] {iid} | visual_only_by_scene_override={mesh_path} reason={reason}')
                    continue
                except Exception as exc:
                    log_warn(f'Failed visual-only override for {iid} ({mesh_path}): {exc}')
        if str(obj.get('decor_collision_policy', '')).lower() == 'visual_only':
            if not is_proxy and isinstance(mesh_path, str) and Path(mesh_path).exists():
                try:
                    visual_morph, visual_kwargs = stage06._mesh_morph(
                        Path(mesh_path), fixed=True, pose=pose, visualization=True, collision=False
                    )
                    visual_ent = stage06._add_entity(scene, visual_morph)
                    if not stage06._mesh_kwargs_has_pose(visual_kwargs):
                        stage06._apply_entity_pose(visual_ent, pose)
                    static_entities[iid] = visual_ent
                    log_info(f'[binding] {iid} | visual_only_decor_mesh={mesh_path}')
                    continue
                except Exception as exc:
                    log_warn(f'Failed visual-only decor object {iid} ({mesh_path}): {exc}')
        if not is_proxy and isinstance(mesh_path, str) and Path(mesh_path).exists():
            try:
                if isinstance(collision_mesh_path, str) and Path(collision_mesh_path).exists() and str(collision_mesh_path) != str(mesh_path):
                    visual_morph, visual_kwargs = stage06._mesh_morph(
                        Path(mesh_path), fixed=True, pose=pose, visualization=True, collision=False
                    )
                    visual_ent = stage06._add_entity(scene, visual_morph)
                    if not stage06._mesh_kwargs_has_pose(visual_kwargs):
                        stage06._apply_entity_pose(visual_ent, pose)
                    collision_morph, collision_kwargs = stage06._mesh_morph(
                        Path(collision_mesh_path),
                        fixed=True,
                        pose=pose,
                        decimate=True,
                        convexify=True,
                        visualization=False,
                        collision=True,
                    )
                    collision_ent = stage06._add_entity(scene, collision_morph)
                    if not stage06._mesh_kwargs_has_pose(collision_kwargs):
                        stage06._apply_entity_pose(collision_ent, pose)
                    static_entities[iid] = collision_ent
                    log_info(f'[binding] {iid} | visual_mesh={mesh_path} | collision_mesh={collision_mesh_path}')
                    continue

                morph, used_kwargs = stage06._mesh_morph(Path(mesh_path), fixed=True, pose=pose)
                ent = stage06._add_entity(scene, morph)
                static_entities[iid] = ent
                if not stage06._mesh_kwargs_has_pose(used_kwargs):
                    stage06._apply_entity_pose(ent, pose)
                continue
            except Exception as exc:
                log_warn(f'Failed to load object mesh {iid} ({mesh_path}): {exc}')

        try:
            added = stage06._proxy_add(scene, obj, fixed=True)
            if added <= 0:
                log_warn(f'Object skipped (no mesh/proxy): {iid}')
        except Exception as exc:
            log_warn(f'Failed proxy object {iid}: {exc}')

    return static_entities


# --------------------------- dynamic objects ---------------------------

def _make_dynamic_morph(stage06: Any, spec: dict[str, Any]) -> Any:
    gs = stage06.gs
    pose = spec.get('pose', {})
    pos = stage06._to_tuple3(pose.get('position'), (0.0, 0.0, 0.5))
    orientation: dict[str, tuple[float, ...]] = {}
    quat_xyzw = pose.get('quaternion_xyzw')
    euler_xyz = pose.get('euler_xyz')
    if isinstance(quat_xyzw, (list, tuple)) and len(quat_xyzw) >= 4:
        # Genesis morphs use wxyz, while the dataset schema uses xyzw.
        orientation['quat'] = (
            float(quat_xyzw[3]),
            float(quat_xyzw[0]),
            float(quat_xyzw[1]),
            float(quat_xyzw[2]),
        )
    elif isinstance(euler_xyz, (list, tuple)) and len(euler_xyz) >= 3:
        # Genesis morph euler values are degrees and must be supplied before
        # scene.build(); entity pose setters are unavailable at this stage.
        orientation['euler'] = tuple(float(value) for value in euler_xyz[:3])
    fixed = bool(spec.get('fixed', False))
    shape = str(spec.get('shape', 'sphere')).lower()

    mesh_path = spec.get('mesh_path')
    if isinstance(mesh_path, str) and mesh_path.strip():
        morph, _ = stage06._mesh_morph(
            Path(mesh_path),
            fixed=fixed,
            pose=pose,
            decimate=bool(spec.get('decimate', False)),
            convexify=bool(spec.get('convexify', False)),
            visualization=bool(spec.get('visualization', True)),
            collision=bool(spec.get('collision', True)),
        )
        return morph

    if shape == 'sphere':
        radius = float(spec.get('radius', 0.05))
        return stage06._try_call_variants(
            gs.morphs.Sphere,
            [
                {'pos': pos, **orientation, 'radius': radius, 'fixed': fixed},
                {'radius': radius, 'fixed': fixed},
                {'pos': pos, 'radius': radius},
                {'radius': radius},
            ],
            'gs.morphs.Sphere',
        )

    if shape == 'box':
        size = spec.get('size', [0.08, 0.08, 0.08])
        if not (isinstance(size, (list, tuple)) and len(size) >= 3):
            size = [0.08, 0.08, 0.08]
        vis = bool(spec.get('visualization', True))
        coll = bool(spec.get('collision', True))
        common = {'pos': pos, **orientation, 'size': (float(size[0]), float(size[1]), float(size[2])), 'fixed': fixed, 'visualization': vis, 'collision': coll}
        return stage06._try_call_variants(
            gs.morphs.Box,
            [
                common,
                {'pos': pos, **orientation, 'extents': (float(size[0]), float(size[1]), float(size[2])), 'fixed': fixed, 'visualization': vis, 'collision': coll},
                {'pos': pos, **orientation, 'size': (float(size[0]), float(size[1]), float(size[2])), 'fixed': fixed},
                {'pos': pos, 'extents': (float(size[0]), float(size[1]), float(size[2])), 'fixed': fixed},
                {'size': (float(size[0]), float(size[1]), float(size[2])), 'fixed': fixed},
                {'size': (float(size[0]), float(size[1]), float(size[2]))},
            ],
            'gs.morphs.Box',
        )

    if shape == 'cylinder':
        radius = float(spec.get('radius', 0.04))
        height = float(spec.get('height', 0.12))
        return stage06._try_call_variants(
            gs.morphs.Cylinder,
            [
                {'pos': pos, **orientation, 'radius': radius, 'height': height, 'fixed': fixed},
                {'radius': radius, 'height': height, 'fixed': fixed},
                {'pos': pos, 'radius': radius, 'height': height},
                {'radius': radius, 'height': height},
            ],
            'gs.morphs.Cylinder',
        )

    raise ValueError(f'Unsupported dynamic shape: {shape}')


def _make_rigid_material_for_spec(stage06: Any, rgb: tuple[float, float, float], spec: dict[str, Any]) -> Any:
    gs = stage06.gs
    friction = spec.get('friction')
    # Color belongs to the render surface, not gs.materials.Rigid.  Passing
    # render keys (and unsupported restitution aliases) made every rich
    # constructor fail and silently selected the default-friction material.
    variants: list[dict[str, Any]] = []
    if friction is not None:
        variants.append({'friction': float(friction), 'coup_friction': float(friction)})
        variants.append({'friction': float(friction)})
    variants.append({})
    for kwargs in variants:
        try:
            return gs.materials.Rigid(**kwargs)
        except Exception:
            continue
    return stage06._make_rigid_material(rgb)


def _best_effort_apply_entity_properties(entity: Any, spec: dict[str, Any]) -> None:
    """Optional properties; silently skip unsupported APIs."""
    if not isinstance(spec, dict):
        return
    # Match the proven T16-T20 renderer guard.  Genesis 0.4.1 may trigger an
    # asynchronous CUDA index assertion when post-build mass/property setters
    # are called on world-fixed kinematic collision proxies.  Their friction is
    # already supplied when the rigid material is constructed; mass/damping do
    # not affect fixed actuators.
    if bool(spec.get('fixed', False)):
        return

    mass = spec.get('mass')
    if mass is not None:
        for name in ('set_mass', 'set_link_mass', 'set_rigid_mass'):
            if hasattr(entity, name):
                try:
                    getattr(entity, name)(float(mass))
                    break
                except Exception:
                    continue

    friction = spec.get('friction')
    if friction is not None:
        for name in ('set_friction', 'set_friction_ratio', 'set_surface_friction'):
            if hasattr(entity, name):
                try:
                    getattr(entity, name)(float(friction))
                    break
                except Exception:
                    continue

    restitution = spec.get('restitution')
    if restitution is not None:
        for name in ('set_restitution', 'set_bounciness'):
            if hasattr(entity, name):
                try:
                    getattr(entity, name)(float(restitution))
                    break
                except Exception:
                    continue

    # Optional rigid-body damping mapping for material-driven experiments.
    linear_damping = spec.get('linear_damping')
    angular_damping = spec.get('angular_damping')
    damping = spec.get('damping')
    if linear_damping is None and isinstance(damping, (int, float)):
        linear_damping = float(damping)
    if angular_damping is None and isinstance(damping, (int, float)):
        angular_damping = float(damping)

    if linear_damping is not None or angular_damping is not None:
        lin = float(linear_damping) if linear_damping is not None else 0.0
        ang = float(angular_damping) if angular_damping is not None else lin

        if hasattr(entity, 'set_dofs_damping'):
            try:
                entity.set_dofs_damping([lin, lin, lin], [0, 1, 2])
            except Exception:
                pass
            try:
                entity.set_dofs_damping([ang, ang, ang], [3, 4, 5])
            except Exception:
                pass
            try:
                entity.set_dofs_damping([lin, lin, lin, ang, ang, ang])
            except Exception:
                pass

        if linear_damping is not None:
            for name in ('set_linear_damping',):
                if hasattr(entity, name):
                    try:
                        getattr(entity, name)(lin)
                        break
                    except Exception:
                        continue

        if angular_damping is not None:
            for name in ('set_angular_damping',):
                if hasattr(entity, name):
                    try:
                        getattr(entity, name)(ang)
                        break
                    except Exception:
                        continue

    if bool(spec.get('ccd_enabled', spec.get('enable_ccd', False))):
        for name in ('enable_ccd', 'set_ccd_enabled', 'set_enable_ccd', 'set_continuous_collision_detection'):
            if not hasattr(entity, name):
                continue
            try:
                getattr(entity, name)(True)
                break
            except TypeError:
                try:
                    getattr(entity, name)()
                    break
                except Exception:
                    continue
            except Exception:
                continue
    if spec.get('contact_offset') is not None:
        offset = float(spec.get('contact_offset'))
        for name in ('set_contact_offset', 'set_collision_margin', 'set_contact_margin'):
            if not hasattr(entity, name):
                continue
            try:
                getattr(entity, name)(offset)
                break
            except Exception:
                continue


def _read_effective_entity_properties(entries: list[dict[str, Any]]) -> dict[str, Any]:
    """Record the solver-side mass/friction values used by dataset actors.

    Commanded parameters alone are insufficient evidence for a physics
    dataset: a constructor fallback can silently replace them with defaults.
    This snapshot makes each delivered sample self-auditing.
    """
    result: dict[str, Any] = {}
    for entry in entries:
        entity = entry.get('entity')
        spec = entry.get('spec', {}) if isinstance(entry.get('spec'), dict) else {}
        item: dict[str, Any] = {
            'commanded_mass_kg': spec.get('mass'),
            'commanded_friction_coefficient': spec.get('friction'),
        }
        try:
            item['effective_mass_kg'] = float(np.asarray(entity.get_mass()).reshape(-1)[0])
        except Exception as exc:
            item['mass_readback_error'] = str(exc)
        try:
            item['effective_geom_friction_coefficients'] = [float(geom.friction) for geom in entity.geoms]
        except Exception as exc:
            item['friction_readback_error'] = str(exc)
        try:
            damping = entity.get_dofs_damping()
            if hasattr(damping, 'detach'):
                damping = damping.detach()
            if hasattr(damping, 'cpu'):
                damping = damping.cpu()
            if hasattr(damping, 'numpy'):
                damping = damping.numpy()
            item['effective_dof_damping'] = [float(value) for value in np.asarray(damping).reshape(-1)]
        except Exception as exc:
            item['damping_readback_error'] = str(exc)
        result[str(entry.get('name', 'unnamed'))] = item
    return result


def _best_effort_disable_sleep(entity: Any, spec: dict[str, Any]) -> None:
    """Disable rigid body sleep where the Genesis build exposes a compatible API."""
    if not isinstance(spec, dict):
        return
    disable_sleep = bool(spec.get('disable_sleep', spec.get('sleep_disabled', False)))
    threshold = spec.get('sleep_threshold')
    if not disable_sleep and threshold is None:
        return

    if disable_sleep:
        for name in (
            'disable_sleep',
            'set_sleep_disabled',
            'set_sleeping_enabled',
            'enable_sleep',
            'set_enable_sleep',
        ):
            if not hasattr(entity, name):
                continue
            fn = getattr(entity, name)
            for args in ((), (True,), (False,)):
                try:
                    if name in ('set_sleeping_enabled', 'enable_sleep', 'set_enable_sleep') and args == (True,):
                        continue
                    fn(*args)
                    break
                except Exception:
                    continue
    if threshold is not None:
        thr = float(threshold)
        for name in ('set_sleep_threshold', 'set_sleeping_threshold', 'set_sleep_energy_threshold'):
            if not hasattr(entity, name):
                continue
            try:
                getattr(entity, name)(thr)
                break
            except Exception:
                continue


def _apply_static_object_overrides(static_entities: dict[str, Any], overrides: Any) -> None:
    if not isinstance(overrides, list):
        return
    for item in overrides:
        if not isinstance(item, dict):
            continue
        iid = str(item.get('instance_id', '')).strip()
        if not iid:
            continue
        ent = static_entities.get(iid)
        if ent is None:
            log_warn(f'static override target not found: {iid}')
            continue
        _best_effort_apply_entity_properties(ent, item)
        log_info(
            f'static override applied: {iid} | '
            f'restitution={item.get("restitution", "<none>")} '
            f'friction={item.get("friction", "<none>")} '
            f'mass={item.get("mass", "<none>")}'
        )


def _reapply_dynamic_object_properties(dynamic_entries: list[dict[str, Any]]) -> None:
    """Re-apply dynamic properties after `scene.build()`.

    Some Genesis APIs (for example mass/friction setters) are available only
    after the entity is fully built in solver space.
    """
    for entry in dynamic_entries:
        ent = entry.get("entity")
        spec = entry.get("spec", {})
        if ent is None or not isinstance(spec, dict):
            continue
        _best_effort_apply_entity_properties(ent, spec)
        _best_effort_disable_sleep(ent, spec)


def _make_colored_surface(stage06: Any, rgb: tuple[float, float, float], spec: dict[str, Any] | None = None) -> Any | None:
    gs = stage06.gs
    if not (hasattr(gs, 'surfaces') and hasattr(gs.surfaces, 'Default')):
        return None
    spec = spec if isinstance(spec, dict) else {}
    material_preset = str(spec.get('material_preset', spec.get('material_type', ''))).lower()
    roughness = spec.get('roughness')
    metallic = spec.get('metallic')
    opacity = spec.get('opacity')
    rich: dict[str, Any] = {'color': rgb}
    diffuse_texture_path = spec.get('diffuse_texture_path')
    if isinstance(diffuse_texture_path, str) and diffuse_texture_path.strip():
        texture_path = Path(diffuse_texture_path)
        if texture_path.exists() and hasattr(gs, 'textures') and hasattr(gs.textures, 'ImageTexture'):
            try:
                rich['diffuse_texture'] = gs.textures.ImageTexture(image_path=str(texture_path), encoding='srgb')
                # Preserve the authored albedo instead of multiplying it by
                # the primitive's fallback display color.
                rich['color'] = (1.0, 1.0, 1.0)
            except Exception as exc:
                log_warn(f'diffuse texture unavailable for {spec.get("name", "surface")}: {exc}')
    if roughness is not None:
        rich['roughness'] = float(roughness)
    if metallic is not None:
        rich['metallic'] = float(metallic)
    if opacity is not None:
        rich['opacity'] = float(opacity)
    for key in ('ior', 'specular_trans', 'diffuse_trans'):
        if spec.get(key) is not None:
            rich[key] = float(spec[key])
    emissive = spec.get('emissive')
    if isinstance(emissive, (list, tuple)) and len(emissive) >= 3:
        rich['emissive'] = tuple(float(x) for x in emissive[:3])
    if material_preset == 'glass' and hasattr(gs.surfaces, 'Glass'):
        glass_kwargs = {
            'color': rgb,
            'roughness': float(roughness) if roughness is not None else 0.018,
            'opacity': float(opacity) if opacity is not None else 0.46,
            'ior': float(spec.get('ior', 1.46)),
            'thickness': float(spec.get('thickness', 0.04)),
        }
        for kwargs in (
            glass_kwargs,
            {k: v for k, v in glass_kwargs.items() if k != 'thickness'},
            {k: v for k, v in glass_kwargs.items() if k not in ('thickness', 'opacity')},
            {'color': rgb, 'roughness': glass_kwargs['roughness'], 'ior': glass_kwargs['ior']},
        ):
            try:
                return gs.surfaces.Glass(**kwargs)
            except Exception:
                continue
    variants = [
        rich,
        {'color': rgb},
        {'base_color': rgb},
        {'diffuse': rgb},
        {'albedo': rgb},
        {},
    ]
    for kwargs in variants:
        try:
            return gs.surfaces.Default(**kwargs)
        except Exception:
            continue
    return None


def _add_dynamic_entity(stage06: Any, scene: Any, morph: Any, material: Any, rgb: tuple[float, float, float]) -> Any:
    surface = _make_colored_surface(stage06, rgb, None)
    variants: list[dict[str, Any]] = []
    if surface is not None:
        variants.append({'morph': morph, 'material': material, 'surface': surface})
        variants.append({'morph': morph, 'surface': surface})
    variants.append({'morph': morph, 'material': material})
    variants.append({'morph': morph})
    return stage06._try_call_variants(scene.add_entity, variants, 'scene.add_entity(dynamic)')


def _add_dynamic_objects(stage06: Any, scene: Any, dynamic_specs: list[dict[str, Any]]) -> list[dict[str, Any]]:
    entities: list[dict[str, Any]] = []
    for idx, spec in enumerate(dynamic_specs):
        if not isinstance(spec, dict):
            continue
        pose = spec.get('pose', {})
        rgb = tuple(float(x) for x in spec.get('color', [0.85, 0.25, 0.25])[:3])
        material = _make_rigid_material_for_spec(stage06, rgb, spec)
        visual_path = spec.get('visual_mesh_path')
        collision_path = spec.get('collision_mesh_path')
        collision_proxy = str(spec.get('collision_proxy', '')).strip().lower()
        split_mesh = isinstance(visual_path, str) and bool(visual_path.strip()) and (
            collision_proxy in {'box', 'sphere', 'cylinder'}
            or (
                isinstance(collision_path, str) and bool(collision_path.strip())
                and visual_path != collision_path
            )
        )
        visual_ent = None
        if split_mesh:
            collision_spec = dict(spec)
            if collision_proxy == 'box':
                proxy_size = spec.get('collision_proxy_size', spec.get('size', [0.08, 0.08, 0.08]))
                collision_spec.update(
                    mesh_path=None,
                    shape='box',
                    size=proxy_size,
                    visualization=False,
                    collision=True,
                    preserve_mesh_material=False,
                )
                log_info(f'[collision_proxy] {spec.get("name", idx)} box size={proxy_size}')
            elif collision_proxy == 'sphere':
                proxy_radius = float(spec.get('collision_proxy_radius', spec.get('radius', 0.05)))
                collision_spec.update(
                    mesh_path=None,
                    shape='sphere',
                    radius=proxy_radius,
                    visualization=False,
                    collision=True,
                    preserve_mesh_material=False,
                )
                log_info(f'[collision_proxy] {spec.get("name", idx)} sphere radius={proxy_radius}')
            elif collision_proxy == 'cylinder':
                proxy_radius = float(spec.get('collision_proxy_radius', spec.get('radius', 0.05)))
                proxy_height = float(spec.get('collision_proxy_height', spec.get('height', 0.10)))
                collision_spec.update(
                    mesh_path=None,
                    shape='cylinder',
                    radius=proxy_radius,
                    height=proxy_height,
                    visualization=False,
                    collision=True,
                    preserve_mesh_material=False,
                )
                log_info(
                    f'[collision_proxy] {spec.get("name", idx)} '
                    f'cylinder radius={proxy_radius} height={proxy_height}'
                )
            else:
                collision_spec.update(mesh_path=collision_path, visualization=False, collision=True, preserve_mesh_material=False)
            morph = _make_dynamic_morph(stage06, collision_spec)
        else:
            morph = _make_dynamic_morph(stage06, spec)
        # A split collision entity is invisible and must receive the explicit
        # rigid material.  Treating it as a material-preserving visual mesh
        # silently selected Genesis' default friction (1.0); fixed ramps then
        # skipped the post-build setter and ignored the dataset coefficient.
        preserve_mesh_material = (
            bool(spec.get('preserve_mesh_material', False))
            and bool(spec.get('mesh_path'))
            and not split_mesh
        )
        if preserve_mesh_material:
            surface = None
        elif split_mesh:
            # Collision proxies must remain physically active but visually
            # transparent; the synchronized authored mesh supplies the look.
            invisible_spec = dict(spec)
            invisible_spec.pop('diffuse_texture_path', None)
            invisible_spec['opacity'] = 0.0
            surface = _make_colored_surface(stage06, rgb, invisible_spec)
        else:
            surface = _make_colored_surface(stage06, rgb, spec)
        if preserve_mesh_material:
            ent = stage06._try_call_variants(
                scene.add_entity,
                [{'morph': morph}, {'morph': morph, 'material': material}],
                'scene.add_entity(dynamic mesh material-preserve)',
            )
        elif surface is not None:
            ent = stage06._try_call_variants(
                scene.add_entity,
                [{'morph': morph, 'material': material, 'surface': surface}, {'morph': morph, 'surface': surface}, {'morph': morph, 'material': material}, {'morph': morph}],
                'scene.add_entity(dynamic)',
            )
        else:
            ent = _add_dynamic_entity(stage06, scene, morph, material, rgb)
        if split_mesh:
            visual_spec = dict(spec)
            visual_spec.update(mesh_path=visual_path, fixed=True, visualization=True, collision=False, preserve_mesh_material=True)
            visual_morph = _make_dynamic_morph(stage06, visual_spec)
            visual_ent = stage06._try_call_variants(
                scene.add_entity,
                [{'morph': visual_morph}, {'morph': visual_morph, 'material': material}],
                'scene.add_entity(v7 visual proxy)',
            )
        if isinstance(pose, dict):
            try:
                stage06._apply_entity_pose(ent, pose)
                if visual_ent is not None:
                    stage06._apply_entity_pose(visual_ent, pose)
            except Exception:
                pass
        _best_effort_apply_entity_properties(ent, spec)
        _best_effort_disable_sleep(ent, spec)
        entities.append(
            {
                'name': str(spec.get('name', f'dyn_{idx:03d}')),
                'entity': ent,
                'visual_entity': visual_ent,
                'spec': spec,
                'initial_position': np.asarray(stage06._to_tuple3(pose.get('position'), (0.0, 0.0, 0.5)), dtype=float),
                'camera_focus': bool(spec.get('camera_focus', True)),
            }
        )
    return entities


def _sync_v7_visual_proxies(dynamic_entries: list[dict[str, Any]]) -> None:
    """Copy collision poses to fixed visual proxies after each physics step."""
    for entry in dynamic_entries:
        # Context assets are fixed in both representations. Re-applying their
        # unchanged pose at every substep is unnecessary and becomes dominant
        # in complex multi-book study scenes.
        spec = entry.get('spec', {})
        if isinstance(spec, dict) and bool(spec.get('fixed', False)):
            motion = spec.get('motion', {}) if isinstance(spec.get('motion'), dict) else {}
            # Script-driven trigger/release objects are intentionally fixed in
            # the solver, but their collision proxy still moves every frame.
            # Keep the authored visual mesh synchronized for those objects.
            if not str(motion.get('type', '')).lower().startswith('scripted_'):
                continue
        visual = entry.get('visual_entity')
        collision = entry.get('entity')
        if visual is None or collision is None:
            continue
        try:
            visual.set_pos(collision.get_pos(), zero_velocity=True)
            visual.set_quat(collision.get_quat(), zero_velocity=True)
        except Exception as exc:
            raise RuntimeError(f"v7 visual/collision sync failed for {entry.get('name')}: {exc}") from exc


def _read_entity_pos(entity: Any, fallback: np.ndarray) -> np.ndarray:
    for name in ('get_pos', 'get_position'):
        if hasattr(entity, name):
            fn = getattr(entity, name)
            try:
                out = fn()
                if hasattr(out, 'detach'):
                    out = out.detach().cpu().numpy()
                arr = np.asarray(out, dtype=float).reshape(-1)
                if arr.size >= 3:
                    return arr[:3]
            except Exception:
                continue
    return fallback.copy()


def _read_entity_quat(entity: Any) -> np.ndarray | None:
    """Return the Genesis rigid pose quaternion in the annotation's xyzw order.

    Genesis exposes entity quaternions in wxyz order.  Keeping that raw order
    under the old ``quaternion_xyzw`` field made oriented extents (and thus
    penetration QA) incorrect even though angle deltas happened to remain
    order-invariant.
    """
    for name in ('get_quat', 'get_quaternion', 'get_orientation'):
        if not hasattr(entity, name):
            continue
        try:
            out = getattr(entity, name)()
            if hasattr(out, 'detach'):
                out = out.detach().cpu().numpy()
            arr = np.asarray(out, dtype=float).reshape(-1)
            if arr.size >= 4 and np.all(np.isfinite(arr[:4])):
                quat_wxyz = arr[:4]
                norm = float(np.linalg.norm(quat_wxyz))
                if norm > 1e-12:
                    quat_wxyz = quat_wxyz / norm
                    return quat_wxyz[[1, 2, 3, 0]]
        except Exception:
            continue
    return None


def _verify_initial_primitive_orientations(stage06: Any, dynamic_entries: list[dict[str, Any]], tolerance_deg: float = 0.5) -> dict[str, Any]:
    """Fail fast when a primitive's configured orientation was not built."""
    checked: list[dict[str, Any]] = []
    failures: list[dict[str, Any]] = []
    for entry in dynamic_entries:
        spec = entry.get('spec', {})
        euler = spec.get('pose', {}).get('euler_xyz')
        if not (isinstance(euler, (list, tuple)) and len(euler) >= 3):
            continue
        actual_xyzw = _read_entity_quat(entry.get('entity'))
        if actual_xyzw is None:
            failures.append({'name': entry.get('name'), 'reason': 'quaternion_unavailable'})
            continue
        expected_wxyz = np.asarray(
            stage06.gs.utils.geom.xyz_to_quat(np.asarray(euler[:3], dtype=float), rpy=True, degrees=True),
            dtype=float,
        ).reshape(-1)[:4]
        expected_xyzw = expected_wxyz[[1, 2, 3, 0]]
        dot = abs(float(np.dot(actual_xyzw, expected_xyzw)))
        error_deg = math.degrees(2.0 * math.acos(max(-1.0, min(1.0, dot))))
        row = {'name': entry.get('name'), 'error_deg': float(error_deg)}
        checked.append(row)
        if error_deg > tolerance_deg:
            failures.append(row)
    if failures:
        raise RuntimeError(f'Initial primitive orientation verification failed: {failures[:8]}')
    result = {
        'checked_count': len(checked),
        'max_error_deg': max((row['error_deg'] for row in checked), default=0.0),
        'tolerance_deg': float(tolerance_deg),
    }
    log_info(f'[POSE_QA] initial primitive orientations verified: {result}')
    return result


def _build_geom_name_map(dynamic_entries: list[dict[str, Any]]) -> dict[int, str]:
    """Map Genesis collision-geometry ids back to event actor names."""
    result: dict[int, str] = {}
    for entry in dynamic_entries:
        entity = entry.get('entity')
        name = str(entry.get('name', ''))
        if entity is None or not name:
            continue
        try:
            for geom in getattr(entity, 'geoms', ()):
                idx = getattr(geom, 'idx', None)
                if idx is not None:
                    result[int(idx)] = name
        except Exception:
            pass
        try:
            geom_start = int(getattr(entity, 'geom_start'))
            geom_end = int(getattr(entity, 'geom_end'))
            for geom_idx in range(geom_start, geom_end):
                result.setdefault(geom_idx, name)
        except Exception:
            pass
    return result


def _read_scene_contacts(scene: Any, geom_name_map: dict[int, str], physics_step_index: int) -> list[dict[str, Any]]:
    """Read the resolved contacts for one physics step for causal QA.

    Keeping actor-pair evidence in the annotation makes it possible to tell a
    genuine impact chain from an object launched by a bad support contact.
    """
    try:
        contacts = scene.sim.rigid_solver.collider.get_contacts(as_tensor=False, to_torch=False)
    except Exception as exc:
        log_warn(f'[CONTACT_QA] unable to read contacts: {type(exc).__name__}: {exc}')
        return []

    def _array(key: str, width: int | None = None) -> np.ndarray:
        raw = contacts.get(key, [])
        if hasattr(raw, 'detach'):
            raw = raw.detach().cpu().numpy()
        arr = np.asarray(raw)
        if width is None:
            return arr.reshape(-1)
        return arr.reshape((-1, width)) if arr.size else np.empty((0, width), dtype=float)

    try:
        geom_a = _array('geom_a')
        geom_b = _array('geom_b')
        penetration = _array('penetration')
        position = _array('position', 3)
        normal = _array('normal', 3)
        force = _array('force', 3)
    except Exception as exc:
        log_warn(f'[CONTACT_QA] malformed contact arrays: {type(exc).__name__}: {exc}')
        return []

    count = min(len(geom_a), len(geom_b), len(penetration), len(position), len(normal), len(force))
    rows: list[dict[str, Any]] = []
    for idx in range(count):
        ga = int(geom_a[idx])
        gb = int(geom_b[idx])
        name_a = geom_name_map.get(ga)
        name_b = geom_name_map.get(gb)
        if name_a is None and name_b is None:
            continue
        penetration_m = float(penetration[idx])
        force_xyz = [float(x) for x in force[idx]]
        # A resting domino contributes four slab contacts on every 1/240 s
        # step.  They are not causal events and would bloat an 8 s annotation
        # by ~200k rows.  Keep only anomalous support contacts; the geometric
        # penetration QA independently checks normal resting support.
        names = {name_a, name_b}
        is_support_contact = bool(
            names.intersection({
                'event_chain_support_surface_collision_slab',
                't08_floor_collision_slab',
            })
        )
        force_norm = math.sqrt(sum(value * value for value in force_xyz))
        if is_support_contact and penetration_m <= 0.003 and force_norm <= 10.0:
            continue
        rows.append(
            {
                'physics_step_index': int(physics_step_index),
                'entity_a': name_a or f'static_geom_{ga}',
                'entity_b': name_b or f'static_geom_{gb}',
                'geom_a': ga,
                'geom_b': gb,
                'penetration_m': penetration_m,
                'position': [float(x) for x in position[idx]],
                'normal': [float(x) for x in normal[idx]],
                'force': force_xyz,
            }
        )
    return rows


def _read_entity_vel(entity: Any) -> np.ndarray | None:
    for name in ('get_vel', 'get_velocity', 'get_linear_velocity'):
        if hasattr(entity, name):
            try:
                out = getattr(entity, name)()
                if hasattr(out, 'detach'):
                    out = out.detach().cpu().numpy()
                arr = np.asarray(out, dtype=float).reshape(-1)
                if arr.size >= 3:
                    return arr[:3]
            except Exception:
                continue
    for name in ('get_dofs_velocity', 'get_dofs_vel'):
        if hasattr(entity, name):
            try:
                out = getattr(entity, name)()
                if hasattr(out, 'detach'):
                    out = out.detach().cpu().numpy()
                arr = np.asarray(out, dtype=float).reshape(-1)
                if arr.size >= 3:
                    return arr[:3]
            except Exception:
                continue
    return None


def _read_entity_ang_vel(entity: Any) -> np.ndarray | None:
    for name in ('get_ang', 'get_ang_vel', 'get_angular_velocity'):
        if not hasattr(entity, name):
            continue
        try:
            out = getattr(entity, name)()
            if hasattr(out, 'detach'):
                out = out.detach().cpu().numpy()
            arr = np.asarray(out, dtype=float).reshape(-1)
            if arr.size >= 3 and np.all(np.isfinite(arr[:3])):
                return arr[:3]
        except Exception:
            continue
    return None


def _try_set_entity_pos(entity: Any, pos: np.ndarray) -> bool:
    p = tuple(float(x) for x in pos[:3])
    if hasattr(entity, 'set_pos'):
        try:
            entity.set_pos(p, zero_velocity=False)
            return True
        except TypeError:
            try:
                entity.set_pos(p)
                return True
            except Exception:
                pass
        except Exception:
            pass
    if hasattr(entity, 'set_position'):
        try:
            entity.set_position(p)
            return True
        except Exception:
            pass
    return False


def _try_set_entity_quat(entity: Any, quat_xyzw: np.ndarray) -> bool:
    # Dataset/keyframe helpers use xyzw, while Genesis rigid entities use
    # wxyz (the same convention as gs.morphs).  Passing xyzw through directly
    # caused a 180-degree pose jump at the pre-static -> scripted boundary.
    x, y, z, w = (float(value) for value in quat_xyzw[:4])
    q = (w, x, y, z)
    for name in ('set_quat', 'set_quaternion'):
        if not hasattr(entity, name):
            continue
        fn = getattr(entity, name)
        try:
            fn(q, zero_velocity=False)
            return True
        except TypeError:
            try:
                fn(q)
                return True
            except Exception:
                continue
        except Exception:
            continue
    return False


def _euler_xyz_to_quat_xyzw(euler_xyz_deg: list[float] | tuple[float, float, float]) -> np.ndarray:
    """Convert intrinsic XYZ degrees to the annotation/entity xyzw convention."""
    rx, ry, rz = (math.radians(float(value)) * 0.5 for value in euler_xyz_deg[:3])
    cx, sx = math.cos(rx), math.sin(rx)
    cy, sy = math.cos(ry), math.sin(ry)
    cz, sz = math.cos(rz), math.sin(rz)
    return np.asarray(
        [
            sx * cy * cz - cx * sy * sz,
            cx * sy * cz + sx * cy * sz,
            cx * cy * sz - sx * sy * cz,
            cx * cy * cz + sx * sy * sz,
        ],
        dtype=float,
    )


def _try_set_velocity(entity: Any, velocity: list[float] | tuple[float, float, float]) -> bool:
    vel = tuple(float(x) for x in velocity[:3])
    # Older/alternate entity APIs.
    for name in ('set_vel', 'set_velocity', 'set_linear_velocity'):
        if not hasattr(entity, name):
            continue
        fn = getattr(entity, name)
        try:
            fn(vel)
            return True
        except TypeError:
            try:
                fn(vel, zero_angular_velocity=True)
                return True
            except Exception:
                pass
        except Exception:
            pass

    # Genesis 0.4.x rigid entity API: translational DOFs are local [0, 1, 2].
    if hasattr(entity, 'set_dofs_velocity'):
        fn = getattr(entity, 'set_dofs_velocity')
        variants = (
            vel,
            [float(vel[0]), float(vel[1]), float(vel[2])],
            np.asarray(vel, dtype=float),
        )
        for v in variants:
            try:
                fn(v, [0, 1, 2])
                return True
            except Exception:
                continue

        # Fallback for APIs expecting full 6-DoF input.
        v6 = np.zeros(6, dtype=float)
        v6[:3] = np.asarray(vel, dtype=float)
        try:
            fn(v6)
            return True
        except Exception:
            pass

    if hasattr(entity, 'control_dofs_velocity'):
        fn = getattr(entity, 'control_dofs_velocity')
        try:
            fn(np.asarray(vel, dtype=float), [0, 1, 2])
            return True
        except Exception:
            pass
    return False


def _try_set_angular_velocity(entity: Any, velocity: list[float] | tuple[float, float, float]) -> bool:
    vel = tuple(float(x) for x in velocity[:3])
    for name in ('set_ang', 'set_ang_vel', 'set_angular_velocity'):
        if not hasattr(entity, name):
            continue
        try:
            getattr(entity, name)(vel)
            return True
        except Exception:
            continue

    if hasattr(entity, 'set_dofs_velocity'):
        fn = getattr(entity, 'set_dofs_velocity')
        variants = (
            vel,
            [float(vel[0]), float(vel[1]), float(vel[2])],
            np.asarray(vel, dtype=float),
        )
        for value in variants:
            try:
                fn(value, [3, 4, 5])
                return True
            except Exception:
                continue

        value6 = np.zeros(6, dtype=float)
        value6[3:] = np.asarray(vel, dtype=float)
        try:
            fn(value6)
            return True
        except Exception:
            pass
    return False


def _try_apply_force(entity: Any, force: list[float] | tuple[float, float, float]) -> tuple[bool, str]:
    f = tuple(float(x) for x in force[:3])
    f_arr = np.asarray(f, dtype=float)
    f_list = [float(f[0]), float(f[1]), float(f[2])]
    origin = (0.0, 0.0, 0.0)
    origin_arr = np.asarray(origin, dtype=float)

    # Most common rigid-body force APIs across Genesis versions/wrappers.
    direct_calls = (
        ('apply_external_force', [(f,), (f_arr,), (f_list,), (f, origin), (f_arr, origin_arr)]),
        ('apply_force', [(f,), (f_arr,), (f_list,), (f, origin), (f_arr, origin_arr)]),
        ('add_force', [(f,), (f_arr,), (f_list,), (f, origin), (f_arr, origin_arr)]),
        ('set_external_force', [(f,), (f_arr,), (f_list,)]),
        ('set_force', [(f,), (f_arr,), (f_list,)]),
    )
    for name, variants in direct_calls:
        if not hasattr(entity, name):
            continue
        fn = getattr(entity, name)
        for args in variants:
            try:
                fn(*args)
                return True, name
            except Exception:
                continue
        try:
            fn(force=f_arr)
            return True, name
        except Exception:
            pass

    # Genesis dofs-based control APIs (translational dofs are [0, 1, 2]).
    dof_calls = (
        'set_dofs_force',
        'control_dofs_force',
        'set_dofs_actuation_force',
        'control_dofs_actuation_force',
    )
    dof_idx_list = [0, 1, 2]
    dof_idx_arr = np.asarray(dof_idx_list, dtype=int)
    for name in dof_calls:
        if not hasattr(entity, name):
            continue
        fn = getattr(entity, name)
        for v in (f, f_list, f_arr):
            for idx in (dof_idx_list, dof_idx_arr):
                try:
                    fn(v, idx)
                    return True, name
                except Exception:
                    continue
        f6 = np.zeros(6, dtype=float)
        f6[:3] = f_arr
        try:
            fn(f6)
            return True, name
        except Exception:
            pass

    return False, ''


def _parse_runtime_forces(exp: dict[str, Any], dynamic_entries: list[dict[str, Any]], frames: int) -> list[dict[str, Any]]:
    raw = exp.get('runtime_forces')
    if not isinstance(raw, list):
        return []
    by_name: dict[str, dict[str, Any]] = {}
    for entry in dynamic_entries:
        name = str(entry.get('name', '')).strip()
        if name:
            by_name[name] = entry

    parsed: list[dict[str, Any]] = []
    for idx, item in enumerate(raw):
        if not isinstance(item, dict):
            continue
        target = str(
            item.get('target')
            or item.get('target_name')
            or item.get('object')
            or item.get('object_name')
            or ''
        ).strip()
        if not target:
            log_warn(f'runtime_force[{idx}] missing target; skip')
            continue
        entry = by_name.get(target)
        if entry is None:
            log_warn(f'runtime_force[{idx}] target not found: {target}; skip')
            continue
        f_raw = item.get('force_world', item.get('force', item.get('force_xyz')))
        if not (isinstance(f_raw, (list, tuple)) and len(f_raw) >= 3):
            log_warn(f'runtime_force[{idx}] invalid force vector for target={target}; skip')
            continue
        force = (float(f_raw[0]), float(f_raw[1]), float(f_raw[2]))

        try:
            frame_start = max(0, int(item.get('frame_start', 0)))
        except Exception:
            frame_start = 0
        try:
            frame_end = int(item.get('frame_end', frames - 1))
        except Exception:
            frame_end = frames - 1
        frame_end = min(frames - 1, max(frame_start, frame_end))
        if frame_start > frames - 1:
            log_warn(f'runtime_force[{idx}] start frame out of range ({frame_start}); skip')
            continue

        name = str(item.get('name', f'runtime_force_{idx:02d}')).strip() or f'runtime_force_{idx:02d}'
        parsed.append(
            {
                'name': name,
                'target': target,
                'entity': entry['entity'],
                'force': force,
                'frame_start': frame_start,
                'frame_end': frame_end,
                'applied_frames': 0,
                'failed_frames': 0,
                'first_method': '',
            }
        )
    return parsed


def _scripted_ease(value: float, mode: str) -> float:
    """Bounded easing curves used by deterministic contact-safe motion paths."""
    t = float(np.clip(value, 0.0, 1.0))
    key = str(mode or 'smootherstep').strip().lower()
    if key in {'linear', 'constant_speed'}:
        return t
    if key in {'ease_in', 'ease_in_cubic', 'gravity'}:
        return t * t * t
    if key in {'ease_out', 'ease_out_cubic', 'impact_decay'}:
        return 1.0 - (1.0 - t) ** 3
    if key in {'ease_in_out', 'ease_in_out_cubic'}:
        return 4.0 * t * t * t if t < 0.5 else 1.0 - ((-2.0 * t + 2.0) ** 3) / 2.0
    if key in {'smoothstep', 'cubic'}:
        return t * t * (3.0 - 2.0 * t)
    # Quintic smootherstep is the default: zero acceleration as well as zero
    # velocity at rest/contact boundaries, avoiding the old robotic snaps.
    return t * t * t * (t * (t * 6.0 - 15.0) + 10.0)


def _keyframe_vec3(
    keyframe: dict[str, Any],
    *,
    absolute_key: str,
    delta_key: str,
    initial: np.ndarray,
) -> np.ndarray:
    raw = keyframe.get(absolute_key)
    if isinstance(raw, (list, tuple)) and len(raw) >= 3:
        return np.asarray(raw[:3], dtype=float)
    raw = keyframe.get(delta_key, [0.0, 0.0, 0.0])
    if isinstance(raw, (list, tuple)) and len(raw) >= 3:
        return initial + np.asarray(raw[:3], dtype=float)
    return initial.copy()


def _apply_scripted_keyframes(
    entry: dict[str, Any],
    motion: dict[str, Any],
    frame_idx: int,
) -> tuple[np.ndarray, np.ndarray]:
    raw_frames = motion.get('keyframes', [])
    if not isinstance(raw_frames, list) or len(raw_frames) < 2:
        raise ValueError(f'scripted_keyframes requires at least two keyframes: {entry["name"]}')
    keyframes = sorted(
        (row for row in raw_frames if isinstance(row, dict)),
        key=lambda row: int(row.get('frame', 0)),
    )
    if len(keyframes) < 2:
        raise ValueError(f'scripted_keyframes has fewer than two valid keyframes: {entry["name"]}')

    initial_pos = entry['initial_position'].copy()
    initial_euler = np.asarray(
        entry['spec'].get('pose', {}).get('euler_xyz', [0.0, 0.0, 0.0]),
        dtype=float,
    ).reshape(-1)[:3]
    if frame_idx <= int(keyframes[0].get('frame', 0)):
        left = right = keyframes[0]
        t = 0.0
    elif frame_idx >= int(keyframes[-1].get('frame', 0)):
        left = right = keyframes[-1]
        t = 1.0
    else:
        left, right = keyframes[0], keyframes[-1]
        for index in range(len(keyframes) - 1):
            candidate_left = keyframes[index]
            candidate_right = keyframes[index + 1]
            if int(candidate_left.get('frame', 0)) <= frame_idx <= int(candidate_right.get('frame', 0)):
                left, right = candidate_left, candidate_right
                break
        start = int(left.get('frame', 0))
        end = max(start + 1, int(right.get('frame', start + 1)))
        raw_t = (frame_idx - start) / float(end - start)
        t = _scripted_ease(raw_t, str(left.get('easing', motion.get('easing', 'smootherstep'))))

    left_pos = _keyframe_vec3(
        left,
        absolute_key='position',
        delta_key='position_delta',
        initial=initial_pos,
    )
    right_pos = _keyframe_vec3(
        right,
        absolute_key='position',
        delta_key='position_delta',
        initial=initial_pos,
    )
    left_euler = _keyframe_vec3(
        left,
        absolute_key='euler_xyz',
        delta_key='euler_delta_xyz',
        initial=initial_euler,
    )
    right_euler = _keyframe_vec3(
        right,
        absolute_key='euler_xyz',
        delta_key='euler_delta_xyz',
        initial=initial_euler,
    )
    return left_pos + t * (right_pos - left_pos), left_euler + t * (right_euler - left_euler)


def _apply_motion_step(entry: dict[str, Any], frame_idx: float) -> dict[str, Any]:
    ent = entry['entity']
    spec = entry['spec']
    motion = spec.get('motion', {})
    if not isinstance(motion, dict):
        motion = {}
    motion_type = str(motion.get('type', 'free_fall')).lower()
    cur = entry.get('last_position', entry['initial_position']).copy()
    applied = {'type': motion_type, 'manual_pose': False}

    if frame_idx == 0:
        init_vel = motion.get('initial_velocity')
        if isinstance(init_vel, (list, tuple)) and len(init_vel) >= 3:
            applied['velocity_set'] = _try_set_velocity(ent, init_vel)
            applied['initial_velocity'] = [float(init_vel[0]), float(init_vel[1]), float(init_vel[2])]
        init_ang_vel = motion.get('initial_angular_velocity')
        if isinstance(init_ang_vel, (list, tuple)) and len(init_ang_vel) >= 3:
            applied['angular_velocity_set'] = _try_set_angular_velocity(ent, init_ang_vel)
            applied['initial_angular_velocity'] = [
                float(init_ang_vel[0]), float(init_ang_vel[1]), float(init_ang_vel[2])
            ]

    if motion_type == 'scripted_keyframes':
        target, interp_euler = _apply_scripted_keyframes(entry, motion, frame_idx)
        pos_ok = _try_set_entity_pos(ent, target)
        quat_ok = _try_set_entity_quat(ent, _euler_xyz_to_quat_xyzw(interp_euler.tolist()))
        if not pos_ok or not quat_ok:
            raise RuntimeError(
                f'scripted_keyframes setter failed for {entry["name"]}: pos_ok={pos_ok}, quat_ok={quat_ok}'
            )
        cur = target
        applied['manual_pose'] = True
        applied['target_position'] = target.tolist()
        applied['target_euler_xyz'] = interp_euler.tolist()

    elif motion_type == 'scripted_translate':
        axis = str(motion.get('axis', 'x')).lower()
        axis_idx = {'x': 0, 'y': 1, 'z': 2}.get(axis, 0)
        distance = float(motion.get('distance', 0.0))
        frames = max(1, int(motion.get('frames', 120)))
        start_frame = max(0, int(motion.get('start_frame', 0)))
        frac = np.clip((frame_idx - start_frame) / max(frames - 1, 1), 0.0, 1.0)
        frac = _scripted_ease(float(frac), str(motion.get('easing', 'smootherstep')))
        target = entry['initial_position'].copy()
        target[axis_idx] += distance * frac
        try:
            ent.set_pos(tuple(target.tolist()), zero_velocity=True)
        except TypeError:
            ent.set_pos(tuple(target.tolist()))
        cur = target
        applied['manual_pose'] = True
        applied['target_position'] = target.tolist()

    elif motion_type == 'scripted_pose':
        start_frame = max(0, int(motion.get('start_frame', 0)))
        motion_frames = max(1, int(motion.get('frames', 30)))
        frac = float(np.clip((frame_idx - start_frame) / max(motion_frames - 1, 1), 0.0, 1.0))
        # Smoothstep keeps the scripted trigger readable and avoids discontinuous
        # velocities at support-release and impact boundaries.
        eased = frac * frac * (3.0 - 2.0 * frac)
        delta = np.asarray(motion.get('position_delta', [0.0, 0.0, 0.0]), dtype=float).reshape(-1)[:3]
        target = entry['initial_position'].copy() + eased * delta
        pos_ok = _try_set_entity_pos(ent, target)
        initial_euler = spec.get('pose', {}).get('euler_xyz', [0.0, 0.0, 0.0])
        final_euler = motion.get('final_euler_xyz', initial_euler)
        start_euler = np.asarray(initial_euler, dtype=float).reshape(-1)[:3]
        end_euler = np.asarray(final_euler, dtype=float).reshape(-1)[:3]
        interp_euler = start_euler + eased * (end_euler - start_euler)
        quat_ok = _try_set_entity_quat(ent, _euler_xyz_to_quat_xyzw(interp_euler.tolist()))
        if not pos_ok or not quat_ok:
            raise RuntimeError(
                f'scripted_pose setter failed for {entry["name"]}: pos_ok={pos_ok}, quat_ok={quat_ok}'
            )
        cur = target
        applied['manual_pose'] = True
        applied['target_position'] = target.tolist()
        applied['target_euler_xyz'] = interp_euler.tolist()

    elif motion_type == 'scripted_circle':
        center = np.asarray(motion.get('center', entry['initial_position'].tolist()), dtype=float)
        radius = float(motion.get('radius', 0.4))
        orbit_frames = max(1, int(motion.get('frames', 180)))
        axis = str(motion.get('axis', 'z')).lower()
        theta = 2.0 * math.pi * (frame_idx / orbit_frames)
        target = center.copy()
        if axis == 'x':
            target[1] += radius * math.cos(theta)
            target[2] += radius * math.sin(theta)
        elif axis == 'y':
            target[0] += radius * math.cos(theta)
            target[2] += radius * math.sin(theta)
        else:
            target[0] += radius * math.cos(theta)
            target[1] += radius * math.sin(theta)
        try:
            ent.set_pos(tuple(target.tolist()), zero_velocity=True)
        except TypeError:
            ent.set_pos(tuple(target.tolist()))
        cur = target
        applied['manual_pose'] = True
        applied['target_position'] = target.tolist()

    elif motion_type in ('free_fall', 'physics', 'impulse', 'set_velocity', 'none'):
        pass

    else:
        log_warn(f'Unknown motion type for {entry["name"]}: {motion_type}, fallback to free_fall')

    entry['last_position'] = cur.copy()
    return applied


def _sphere_radius_from_entry(entry: dict[str, Any]) -> float | None:
    spec = entry.get('spec', {})
    if not isinstance(spec, dict):
        return None
    shape = str(spec.get('shape', '')).lower()
    name = str(entry.get('name', '')).lower()
    if shape != 'sphere' and 'ball' not in name:
        return None
    try:
        return max(1e-4, float(spec.get('radius', 0.05)))
    except Exception:
        return 0.05


def _apply_wall_boundary_safety(
    dynamic_entries: list[dict[str, Any]],
    bounds: dict[str, list[float]] | None,
    scene_cfg: dict[str, Any],
    frame_idx: int,
    physics_step_idx: int,
) -> list[dict[str, Any]]:
    cfg = scene_cfg.get('room_boundary_safety', {})
    if cfg is False or (isinstance(cfg, dict) and cfg.get('enabled') is False):
        return []
    if not isinstance(bounds, dict):
        return []
    cfg = cfg if isinstance(cfg, dict) else {}
    restitution = float(cfg.get('restitution', scene_cfg.get('room_boundary_restitution', 0.72)))
    margin = float(cfg.get('margin', 0.004))
    penetration_tolerance = float(cfg.get('penetration_tolerance', 0.025))
    min_speed = float(cfg.get('min_reflect_speed', 0.02))
    bmin = np.asarray(bounds['min'], dtype=float)
    bmax = np.asarray(bounds['max'], dtype=float)
    events: list[dict[str, Any]] = []
    for entry in dynamic_entries:
        radius = _sphere_radius_from_entry(entry)
        if radius is None:
            continue
        ent = entry.get('entity')
        if ent is None:
            continue
        pos = _read_entity_pos(ent, entry.get('last_position', entry['initial_position']))
        vel = _read_entity_vel(ent)
        if vel is None:
            last = np.asarray(entry.get('last_position', pos), dtype=float)
            vel = pos - last
        new_pos = pos.copy()
        new_vel = vel.copy()
        hit_axes: list[str] = []
        for axis, axis_name in ((0, 'x'), (1, 'y')):
            lower = float(bmin[axis] + radius + margin)
            upper = float(bmax[axis] - radius - margin)
            if new_pos[axis] < lower - penetration_tolerance:
                new_pos[axis] = lower
                if new_vel[axis] < min_speed:
                    new_vel[axis] = abs(new_vel[axis]) * restitution
                hit_axes.append(f'{axis_name}min')
            elif new_pos[axis] > upper + penetration_tolerance:
                new_pos[axis] = upper
                if new_vel[axis] > -min_speed:
                    new_vel[axis] = -abs(new_vel[axis]) * restitution
                hit_axes.append(f'{axis_name}max')
        if hit_axes:
            pos_ok = _try_set_entity_pos(ent, new_pos)
            vel_ok = _try_set_velocity(ent, new_vel.tolist())
            entry['last_position'] = new_pos.copy()
            events.append(
                {
                    'frame': int(frame_idx),
                    'physics_step': int(physics_step_idx),
                    'name': entry['name'],
                    'axes': hit_axes,
                    'position_before': [float(x) for x in pos[:3]],
                    'position_after': [float(x) for x in new_pos[:3]],
                    'velocity_before': [float(x) for x in vel[:3]],
                    'velocity_after': [float(x) for x in new_vel[:3]],
                    'set_position_ok': bool(pos_ok),
                    'set_velocity_ok': bool(vel_ok),
                }
            )
    return events


