def _to_uint8_image(stage06: Any, image: Any) -> np.ndarray:
    if hasattr(stage06, '_to_uint8_image'):
        return stage06._to_uint8_image(image)
    data = image[0] if isinstance(image, tuple) else image
    if hasattr(data, 'detach'):
        data = data.detach().cpu().numpy()
    arr = np.asarray(data)
    if arr.ndim == 4 and arr.shape[0] == 1:
        arr = arr[0]
    if arr.ndim == 2:
        arr = np.stack([arr, arr, arr], axis=-1)
    if arr.shape[-1] > 3:
        arr = arr[..., :3]
    if arr.dtype != np.uint8:
        vmax = float(np.nanmax(arr)) if arr.size else 1.0
        if vmax <= 1.0:
            arr = np.clip(arr, 0.0, 1.0) * 255.0
        arr = np.clip(arr, 0, 255).astype(np.uint8)
    return arr


def _save_depth_png(depth_arr: Any, path: Path) -> None:
    arr = depth_arr
    if hasattr(arr, 'detach'):
        arr = arr.detach().cpu().numpy()
    arr = np.asarray(arr)
    if arr.ndim == 3 and arr.shape[0] == 1:
        arr = arr[0]
    arr = np.nan_to_num(arr, nan=0.0, posinf=0.0, neginf=0.0)
    vmax = float(np.max(arr)) if arr.size else 1.0
    if vmax <= 1e-8:
        vmax = 1.0
    img = np.clip(arr / vmax * 65535.0, 0, 65535).astype(np.uint16)
    safe_makedirs(path)
    Image.fromarray(img).save(path)


def _save_seg_png(seg_arr: Any, path: Path) -> None:
    arr = seg_arr
    if hasattr(arr, 'detach'):
        arr = arr.detach().cpu().numpy()
    arr = np.asarray(arr)
    if arr.ndim == 3 and arr.shape[0] == 1:
        arr = arr[0]
    arr = np.nan_to_num(arr, nan=0).astype(np.uint16)
    safe_makedirs(path)
    Image.fromarray(arr).save(path)


def _estimate_orbit_center(stage09: Any | None, placement_debug: dict[str, Any], layout_mesh: str | None, dynamic_entries: list[dict[str, Any]]) -> tuple[np.ndarray, np.ndarray]:
    if stage09 is not None and hasattr(stage09, '_estimate_orbit_center_and_size'):
        try:
            center, extent = stage09._estimate_orbit_center_and_size(placement_debug, layout_mesh)
            center = np.asarray(center, dtype=float)
            extent = np.asarray(extent, dtype=float)
        except Exception:
            center = np.array([0.0, 0.0, 0.8], dtype=float)
            extent = np.array([4.0, 4.0, 2.0], dtype=float)
    else:
        center = np.array([0.0, 0.0, 0.8], dtype=float)
        extent = np.array([4.0, 4.0, 2.0], dtype=float)

    if dynamic_entries:
        pts = np.stack([x['initial_position'] for x in dynamic_entries], axis=0)
        pmin = pts.min(axis=0)
        pmax = pts.max(axis=0)
        dcenter = 0.5 * (pmin + pmax)
        dextent = np.maximum(pmax - pmin, 1e-4)
        center = 0.35 * center + 0.65 * dcenter
        extent = np.maximum(extent * 0.6, dextent)
    return center, extent


def _get_dynamic_focus_center(dynamic_entries: list[dict[str, Any]]) -> np.ndarray | None:
    pts: list[np.ndarray] = []
    for entry in dynamic_entries:
        if not entry.get('camera_focus', True):
            continue
        pos = _read_entity_pos(entry['entity'], entry.get('last_position', entry['initial_position']))
        pts.append(pos)
    if not pts:
        return None
    arr = np.stack(pts, axis=0)
    return arr.mean(axis=0)


def _camera_defaults_from_manifest(manifest: dict[str, Any]) -> tuple[np.ndarray, np.ndarray, float, tuple[int, int]]:
    cam = manifest.get('camera_defaults', {})
    if not isinstance(cam, dict):
        cam = {}
    pos = np.asarray(_to_vec3(cam.get('overview_pos'), (6.0, -6.0, 4.0)), dtype=float)
    lookat = np.asarray(_to_vec3(cam.get('overview_lookat'), (0.0, 0.0, 0.8)), dtype=float)
    fov = float(cam.get('fov', 70.0))
    res_raw = cam.get('res', [1280, 720])
    if not (isinstance(res_raw, (list, tuple)) and len(res_raw) >= 2):
        res_raw = [1280, 720]
    res = (int(res_raw[0]), int(res_raw[1]))
    return pos, lookat, fov, res


def _compute_camera_init(
    *,
    camera_mode: str,
    render_cfg: dict[str, Any],
    scene_center: np.ndarray,
    dynamic_entries: list[dict[str, Any]],
    fallback_pos: np.ndarray,
    fallback_lookat: np.ndarray,
    fallback_fov: float,
) -> tuple[np.ndarray, np.ndarray, float]:
    focus = scene_center.copy()
    if dynamic_entries:
        pts = np.stack([x['initial_position'] for x in dynamic_entries], axis=0)
        focus = pts.mean(axis=0)

    if camera_mode == 'fixed_view':
        fixed_view = render_cfg.get('fixed_view', {})
        if isinstance(fixed_view, dict):
            pos = np.asarray(_to_vec3(fixed_view.get('position'), tuple(fallback_pos.tolist())), dtype=float)
            lookat = np.asarray(_to_vec3(fixed_view.get('look_at'), tuple(fallback_lookat.tolist())), dtype=float)
            fov = float(fixed_view.get('fov_deg', render_cfg.get('camera_fov_deg', fallback_fov)))
            return pos, lookat, fov

    if camera_mode in ('impact_follow', 'impact_track'):
        impact_center = np.asarray(render_cfg.get('impact_center', focus.tolist()), dtype=float)
        offset = np.asarray(render_cfg.get('impact_offset', [1.15, -0.95, 0.95]), dtype=float)
        lookat_offset = np.asarray(render_cfg.get('impact_lookat_offset', [0.0, 0.0, 0.08]), dtype=float)
        pos = impact_center + offset
        lookat = impact_center + lookat_offset
        fov = float(render_cfg.get('camera_fov_deg', fallback_fov))
        return pos, lookat, fov

    if camera_mode in ('focus_dynamic', 'focus_collision', 'closeup'):
        offset = np.asarray(render_cfg.get('focus_offset', [2.6, -2.4, 1.9]), dtype=float)
        lookat_offset = np.asarray(render_cfg.get('focus_lookat_offset', [0.0, 0.0, 0.35]), dtype=float)
        pos = focus + offset
        lookat = focus + lookat_offset
        fov = float(render_cfg.get('camera_fov_deg', fallback_fov))
        return pos, lookat, fov

    return fallback_pos.copy(), fallback_lookat.copy(), fallback_fov


def _sanitize_camera_pose(
    pos: np.ndarray,
    lookat: np.ndarray,
    focus: np.ndarray,
    *,
    min_look_z: float = 0.08,
    min_pos_z: float = 0.18,
) -> tuple[np.ndarray, np.ndarray, str]:
    reason = ''
    pos = np.asarray(pos, dtype=float).reshape(-1)[:3].copy()
    lookat = np.asarray(lookat, dtype=float).reshape(-1)[:3].copy()
    focus = np.asarray(focus, dtype=float).reshape(-1)[:3].copy()
    if not np.all(np.isfinite(pos)) or not np.all(np.isfinite(lookat)):
        lookat = focus.copy()
        pos = focus + np.asarray([1.8, -1.8, 1.35], dtype=float)
        reason = 'non_finite_pose_replaced'
    if float(np.linalg.norm(pos - lookat)) < 0.08:
        pos = lookat + np.asarray([1.8, -1.8, 1.25], dtype=float)
        reason = (reason + ';' if reason else '') + 'degenerate_pose_reframed'
    lookat[2] = max(float(lookat[2]), float(min_look_z))
    pos[2] = max(float(pos[2]), float(min_pos_z))
    return pos, lookat, reason


def _set_camera_pose_best_effort(camera: Any, pos: np.ndarray, lookat: np.ndarray) -> tuple[bool, str]:
    attempts = (
        ('set_pose', {'pos': tuple(pos.tolist()), 'lookat': tuple(lookat.tolist()), 'up': (0.0, 0.0, 1.0)}),
        ('set_pose', {'pos': tuple(pos.tolist()), 'lookat': tuple(lookat.tolist())}),
        ('set_pose', {'position': tuple(pos.tolist()), 'lookat': tuple(lookat.tolist())}),
    )
    for name, kwargs in attempts:
        if not hasattr(camera, name):
            continue
        try:
            getattr(camera, name)(**kwargs)
            return True, name
        except Exception:
            continue
    return False, ''


def _add_camera_with_render_overrides(
    stage06: Any,
    scene: Any,
    manifest: dict[str, Any],
    render_cfg: dict[str, Any],
    camera_mode: str,
    scene_center: np.ndarray,
    dynamic_entries: list[dict[str, Any]],
) -> tuple[Any, dict[str, Any]]:
    default_pos, default_lookat, default_fov, default_res = _camera_defaults_from_manifest(manifest)
    render_res = render_cfg.get('resolution', render_cfg.get('res'))
    fixed_view = render_cfg.get('fixed_view', {})
    if isinstance(fixed_view, dict):
        render_res = fixed_view.get('resolution', fixed_view.get('res', render_res))
    if isinstance(render_res, (list, tuple)) and len(render_res) >= 2:
        try:
            rw = max(64, int(render_res[0]))
            rh = max(64, int(render_res[1]))
            default_res = (rw, rh)
        except Exception:
            pass
    pos, lookat, fov = _compute_camera_init(
        camera_mode=camera_mode,
        render_cfg=render_cfg,
        scene_center=scene_center,
        dynamic_entries=dynamic_entries,
        fallback_pos=default_pos,
        fallback_lookat=default_lookat,
        fallback_fov=default_fov,
    )
    focus = scene_center.copy()
    if dynamic_entries:
        pts = np.stack([x['initial_position'] for x in dynamic_entries], axis=0)
        focus = pts.mean(axis=0)
    pos, lookat, pose_sanitize_reason = _sanitize_camera_pose(
        pos,
        lookat,
        focus,
        min_look_z=float(render_cfg.get('camera_min_look_z', 0.08)),
        min_pos_z=float(render_cfg.get('camera_min_pos_z', 0.18)),
    )
    dist = float(np.linalg.norm(pos - lookat))
    near = float(render_cfg.get('near', render_cfg.get('near_clip', max(0.005, min(0.03, dist * 0.01)))))
    far = float(render_cfg.get('far', render_cfg.get('far_clip', max(20.0, dist + 12.0))))
    camera = stage06._try_call_variants(
        scene.add_camera,
        [
            {
                'res': default_res,
                'pos': tuple(pos.tolist()),
                'lookat': tuple(lookat.tolist()),
                'fov': float(fov),
                'near': near,
                'far': far,
                'GUI': False,
                'spp': int(render_cfg.get('raytracing_spp', render_cfg.get('spp', 32))),
                'denoise': bool(render_cfg.get('raytracing_denoise', render_cfg.get('denoise', True))),
            },
            {'res': default_res, 'pos': tuple(pos.tolist()), 'lookat': tuple(lookat.tolist()), 'fov': float(fov), 'near': near, 'far': far, 'GUI': False},
            {'res': default_res, 'pos': tuple(pos.tolist()), 'lookat': tuple(lookat.tolist()), 'fov': float(fov), 'GUI': False},
            {'res': default_res, 'fov': float(fov)},
        ],
        'scene.add_camera',
    )
    pose_set, pose_set_method = _set_camera_pose_best_effort(camera, pos, lookat)
    dbg = {
        'camera_mode': camera_mode,
        'position': [float(pos[0]), float(pos[1]), float(pos[2])],
        'look_at': [float(lookat[0]), float(lookat[1]), float(lookat[2])],
        'fov': float(fov),
        'near': near,
        'far': far,
        'res': [int(default_res[0]), int(default_res[1])],
        'distance_to_look_at': dist,
        'pose_sanitize_reason': pose_sanitize_reason,
        'pose_set_after_create': pose_set,
        'pose_set_method': pose_set_method,
        'raytracing_spp': int(render_cfg.get('raytracing_spp', render_cfg.get('spp', 32))),
        'raytracing_denoise': bool(render_cfg.get('raytracing_denoise', render_cfg.get('denoise', True))),
    }
    return camera, dbg


def _update_camera_pose(camera: Any, camera_mode: str, frame_idx: int, frames: int, *, dynamic_entries: list[dict[str, Any]], scene_center: np.ndarray, scene_extent: np.ndarray, render_cfg: dict[str, Any]) -> None:
    center = scene_center.copy()
    focus = _get_dynamic_focus_center(dynamic_entries)
    if focus is not None:
        center = 0.8 * focus + 0.2 * scene_center

    if camera_mode in ('focus_dynamic', 'focus_collision', 'closeup'):
        offset = np.asarray(render_cfg.get('focus_offset', [2.6, -2.4, 1.9]), dtype=float)
        lookat_offset = np.asarray(render_cfg.get('focus_lookat_offset', [0.0, 0.0, 0.35]), dtype=float)
        pos = center + offset
        lookat = center + lookat_offset
        try:
            camera.set_pose(pos=tuple(pos.tolist()), lookat=tuple(lookat.tolist()), up=(0.0, 0.0, 1.0))
        except Exception:
            pass
        return

    if camera_mode in ('impact_follow', 'impact_track'):
        # Camera mode dedicated to drop-hit demos: keep the impact area near the center.
        impact_center = np.asarray(render_cfg.get('impact_center', scene_center.tolist()), dtype=float)
        if focus is not None:
            center = 0.75 * focus + 0.25 * impact_center
        else:
            center = impact_center
        offset = np.asarray(render_cfg.get('impact_offset', [1.15, -0.95, 0.95]), dtype=float)
        lookat_offset = np.asarray(render_cfg.get('impact_lookat_offset', [0.0, 0.0, 0.08]), dtype=float)
        pos = center + offset
        lookat = center + lookat_offset
        try:
            camera.set_pose(pos=tuple(pos.tolist()), lookat=tuple(lookat.tolist()), up=(0.0, 0.0, 1.0))
        except Exception:
            pass
        return

    if camera_mode == 'fixed_view':
        # Fixed view is already applied when creating camera.
        return

    if camera_mode == 'orbit':
        orbit_radius = float(render_cfg.get('radius', max(scene_extent[0], scene_extent[1]) * 1.2 + 0.8))
        orbit_height = float(render_cfg.get('height', max(1.2, scene_extent[2] * 1.1 + 0.9)))
        orbits = float(render_cfg.get('orbits', 1.0))
        start_rad = math.radians(float(render_cfg.get('start_azimuth_deg', 15.0)))
        lookat_z_offset = float(render_cfg.get('lookat_z_offset', 0.5))
        frac = float(frame_idx) / float(max(frames, 1))
        theta = start_rad + frac * 2.0 * math.pi * orbits
        pos = np.array(
            [
                center[0] + orbit_radius * math.cos(theta),
                center[1] + orbit_radius * math.sin(theta),
                center[2] + orbit_height,
            ],
            dtype=float,
        )
        lookat = np.array([center[0], center[1], center[2] + lookat_z_offset], dtype=float)
        try:
            camera.set_pose(pos=tuple(pos.tolist()), lookat=tuple(lookat.tolist()), up=(0.0, 0.0, 1.0))
        except Exception:
            pass
        return

    # fallback fixed / scene-default mode: do nothing


# --------------------------- path helpers ---------------------------

def _resolve_input_path(raw_path: str | Path, *, config_path: Path) -> Path:
    p = Path(str(raw_path))
    if p.is_absolute():
        return p

    script_dir = Path(SOURCE_SCRIPT_PATH).parent
    repo_root = script_dir.parent
    cwd = Path.cwd()
    candidates = [
        config_path.parent / p,
        cwd / p,
        repo_root / p,
        cwd.parent / p,
        repo_root.parent / p,
    ]

    seen = set()
    uniq = []
    for c in candidates:
        try:
            r = c.resolve()
        except Exception:
            r = c
        key = str(r)
        if key in seen:
            continue
        seen.add(key)
        uniq.append(c)

    for c in uniq:
        if c.exists():
            return c

    return candidates[1]


def _fmt_vec3(v: Any) -> str:
    arr = np.asarray(v, dtype=float).reshape(-1)
    if arr.size < 3:
        return str(v)
    return f'[{arr[0]:.3f}, {arr[1]:.3f}, {arr[2]:.3f}]'


def _first_entry(entries: list[dict[str, Any]], name: str) -> dict[str, Any] | None:
    for x in entries:
        if str(x.get('name', '')) == name:
            return x
    return None


def _first_entry_any(entries: list[dict[str, Any]], names: list[str]) -> dict[str, Any] | None:
    for name in names:
        n = str(name).strip()
        if not n:
            continue
        hit = _first_entry(entries, n)
        if hit is not None:
            return hit
    return None


def _safe_unit(vec: np.ndarray, fallback: tuple[float, float, float]) -> np.ndarray:
    n = float(np.linalg.norm(vec))
    if n <= 1e-8:
        return np.asarray(fallback, dtype=float)
    return vec / n


def _point_in_camera_frustum(point: np.ndarray, cam_pos: np.ndarray, cam_look: np.ndarray, fov_deg: float, aspect: float) -> bool:
    forward = _safe_unit(cam_look - cam_pos, (0.0, 1.0, 0.0))
    up_hint = np.array([0.0, 0.0, 1.0], dtype=float)
    if abs(float(np.dot(forward, up_hint))) > 0.98:
        up_hint = np.array([0.0, 1.0, 0.0], dtype=float)
    right = _safe_unit(np.cross(forward, up_hint), (1.0, 0.0, 0.0))
    up = _safe_unit(np.cross(right, forward), (0.0, 0.0, 1.0))

    rel = point - cam_pos
    z = float(np.dot(rel, forward))
    if z <= 1e-6:
        return False

    fov = float(max(5.0, min(170.0, fov_deg)))
    tan_v = math.tan(math.radians(0.5 * fov))
    tan_h = tan_v * max(1e-6, float(aspect))
    x = float(np.dot(rel, right))
    y = float(np.dot(rel, up))
    return abs(x / z) <= tan_h and abs(y / z) <= tan_v


def _visible_ratio(track: list[np.ndarray], cam_pos: np.ndarray, cam_look: np.ndarray, fov_deg: float, aspect: float) -> float:
    if not track:
        return 0.0
    ok = 0
    for p in track:
        if _point_in_camera_frustum(np.asarray(p, dtype=float), cam_pos, cam_look, fov_deg, aspect):
            ok += 1
    return float(ok) / float(len(track))


def _camera_basis(cam_pos: np.ndarray, cam_look: np.ndarray, cam_up_hint: np.ndarray) -> tuple[np.ndarray, np.ndarray, np.ndarray]:
    fwd = _safe_unit(cam_look - cam_pos, (0.0, 1.0, 0.0))
    right = np.cross(fwd, cam_up_hint)
    if float(np.linalg.norm(right)) <= 1e-8:
        right = np.cross(fwd, np.array([0.0, 0.0, 1.0], dtype=float))
    right = _safe_unit(right, (1.0, 0.0, 0.0))
    up = _safe_unit(np.cross(right, fwd), (0.0, 0.0, 1.0))
    return right, up, fwd


def _project_point(point: np.ndarray, *, cam_pos: np.ndarray, cam_right: np.ndarray, cam_up: np.ndarray, cam_fwd: np.ndarray, fov_deg: float, width: int, height: int) -> tuple[float, float, float] | None:
    rel = point - cam_pos
    x = float(np.dot(rel, cam_right))
    y = float(np.dot(rel, cam_up))
    z = float(np.dot(rel, cam_fwd))
    if z <= 1e-6:
        return None
    f = 0.5 * float(height) / max(1e-6, math.tan(math.radians(float(fov_deg)) * 0.5))
    u = 0.5 * float(width) + f * (x / z)
    v = 0.5 * float(height) - f * (y / z)
    return u, v, z


def _render_overlay_rgb_frame(
    *,
    background_rgb: np.ndarray | None,
    width: int,
    height: int,
    frame_idx: int,
    total_frames: int,
    gravity_z: float,
    ball_pos: np.ndarray | None,
    box_pos: np.ndarray | None,
    ball_radius: float | None,
    box_size: tuple[float, float, float] | None,
    target_corner: list[float] | None,
    cam_pos: np.ndarray,
    cam_right: np.ndarray,
    cam_up: np.ndarray,
    cam_fwd: np.ndarray,
    cam_fov: float,
    trails: dict[str, list[tuple[int, int]]],
) -> np.ndarray:
    if cv2 is None:
        raise RuntimeError('OpenCV is required for overlay_2d rendering.')

    if background_rgb is not None:
        frame_rgb = background_rgb.copy()
        if frame_rgb.shape[0] != int(height) or frame_rgb.shape[1] != int(width):
            frame_rgb = cv2.resize(frame_rgb, (int(width), int(height)), interpolation=cv2.INTER_LINEAR)
    else:
        frame_rgb = np.full((int(height), int(width), 3), (28, 32, 40), dtype=np.uint8)
    frame = np.ascontiguousarray(frame_rgb[..., ::-1])  # BGR for OpenCV drawing.

    overlay = frame.copy()
    cv2.rectangle(overlay, (18, 16), (470, 98), (0, 0, 0), thickness=-1)
    frame = cv2.addWeighted(overlay, 0.32, frame, 0.68, 0.0)
    cv2.putText(
        frame,
        f"ball-corner-hit | frame {frame_idx + 1}/{total_frames}",
        (26, 44),
        cv2.FONT_HERSHEY_SIMPLEX,
        0.68,
        (235, 235, 240),
        2,
        cv2.LINE_AA,
    )
    cv2.putText(
        frame,
        f"gravity_z={gravity_z:.3f} m/s^2",
        (26, 76),
        cv2.FONT_HERSHEY_SIMPLEX,
        0.62,
        (235, 235, 240),
        2,
        cv2.LINE_AA,
    )

    def _draw_trail(name: str, point_uv: tuple[int, int], color_bgr: tuple[int, int, int]) -> None:
        trail = trails.setdefault(name, [])
        trail.append(point_uv)
        if len(trail) > 60:
            del trail[:-60]
        if len(trail) >= 2:
            cv2.polylines(frame, [np.asarray(trail, dtype=np.int32)], False, color_bgr, 2, cv2.LINE_AA)

    if target_corner is not None:
        cp = _project_point(
            np.asarray(target_corner, dtype=float),
            cam_pos=cam_pos,
            cam_right=cam_right,
            cam_up=cam_up,
            cam_fwd=cam_fwd,
            fov_deg=cam_fov,
            width=width,
            height=height,
        )
        if cp is not None:
            cu, cv, _ = cp
            cxi, cyi = int(round(cu)), int(round(cv))
            cv2.drawMarker(frame, (cxi, cyi), (0, 220, 255), markerType=cv2.MARKER_CROSS, markerSize=16, thickness=2, line_type=cv2.LINE_AA)
            cv2.putText(frame, "target corner", (cxi + 8, cyi - 8), cv2.FONT_HERSHEY_SIMPLEX, 0.48, (0, 220, 255), 1, cv2.LINE_AA)

    if box_pos is not None:
        bx = _project_point(
            np.asarray(box_pos, dtype=float),
            cam_pos=cam_pos,
            cam_right=cam_right,
            cam_up=cam_up,
            cam_fwd=cam_fwd,
            fov_deg=cam_fov,
            width=width,
            height=height,
        )
        if bx is not None:
            bu, bv, bz = bx
            _draw_trail("box", (int(round(bu)), int(round(bv))), (245, 168, 40))
            half_x = 0.12
            half_y = 0.12
            if box_size is not None:
                half_x = max(0.01, float(box_size[0]) * 0.5)
                half_y = max(0.01, float(box_size[1]) * 0.5)
            sx = max(6, int(round((0.5 * float(height) / max(1e-6, math.tan(math.radians(cam_fov) * 0.5))) * (half_x / max(bz, 0.08)))))
            sy = max(6, int(round((0.5 * float(height) / max(1e-6, math.tan(math.radians(cam_fov) * 0.5))) * (half_y / max(bz, 0.08)))))
            x0 = int(round(bu - sx))
            x1 = int(round(bu + sx))
            y0 = int(round(bv - sy))
            y1 = int(round(bv + sy))
            cv2.rectangle(frame, (x0, y0), (x1, y1), (245, 210, 70), thickness=-1, lineType=cv2.LINE_AA)
            cv2.rectangle(frame, (x0, y0), (x1, y1), (28, 30, 32), thickness=2, lineType=cv2.LINE_AA)
            cv2.putText(frame, "box", (x0 + 4, y0 - 6), cv2.FONT_HERSHEY_SIMPLEX, 0.5, (245, 245, 245), 1, cv2.LINE_AA)

    if ball_pos is not None:
        bp = _project_point(
            np.asarray(ball_pos, dtype=float),
            cam_pos=cam_pos,
            cam_right=cam_right,
            cam_up=cam_up,
            cam_fwd=cam_fwd,
            fov_deg=cam_fov,
            width=width,
            height=height,
        )
        if bp is not None:
            bu, bv, bz = bp
            _draw_trail("ball", (int(round(bu)), int(round(bv))), (75, 105, 255))
            rad = 0.09 if ball_radius is None else max(0.02, float(ball_radius))
            rp = max(4, int(round((0.5 * float(height) / max(1e-6, math.tan(math.radians(cam_fov) * 0.5))) * (rad / max(bz, 0.08)))))
            cv2.circle(frame, (int(round(bu)), int(round(bv))), int(rp), (65, 85, 255), thickness=-1, lineType=cv2.LINE_AA)
            cv2.circle(frame, (int(round(bu)), int(round(bv))), int(rp), (18, 18, 20), thickness=2, lineType=cv2.LINE_AA)
            cv2.putText(frame, "ball", (int(round(bu + 6)), int(round(bv - 8))), cv2.FONT_HERSHEY_SIMPLEX, 0.5, (245, 245, 245), 1, cv2.LINE_AA)

    return np.ascontiguousarray(frame[..., ::-1])  # RGB


