def _bundle_invariant_payload(exp: dict[str, Any]) -> dict[str, Any]:
    """Return the fields that must match across same-scene camera configs."""
    payload = copy.deepcopy(exp)
    payload.pop('camera_id', None)
    payload.pop('trajectory_replay_path', None)
    payload.pop('trajectory_replay_sha256', None)
    payload.pop('_background_anchor', None)
    render = payload.get('render', {})
    if isinstance(render, dict):
        for key in (
            'camera_mode', 'fixed_view', 'focus_offset', 'focus_lookat_offset',
            'impact_offset', 'impact_lookat_offset', 'impact_center',
            'radius', 'height', 'orbits', 'start_azimuth_deg', 'lookat_z_offset',
            'camera_fov_deg', 'near', 'near_clip', 'far', 'far_clip',
            'save_video', 'save_first_rgb', 'save_last_rgb',
            'save_rgb_frames_dir', 'save_depth_dir', 'save_seg_dir',
        ):
            render.pop(key, None)
    annotations = payload.get('annotations', {})
    if isinstance(annotations, dict):
        annotations.pop('save_path', None)
    # Formal sampling metadata correctly records a distinct camera id in each
    # view config.  It is descriptive camera metadata, not simulation state,
    # and therefore must not make a synchronized bundle fail its physics
    # invariant check.
    formal_sampling = payload.get('formal_sampling', {})
    if isinstance(formal_sampling, dict):
        formal_sampling.pop('camera_id', None)
    experiment = payload.get('experiment', {})
    if isinstance(experiment, dict):
        nested_formal = experiment.get('formal_sampling', {})
        if isinstance(nested_formal, dict):
            nested_formal.pop('camera_id', None)
        camera_smoke = experiment.get('camera_smoke', {})
        if isinstance(camera_smoke, dict):
            camera_smoke.pop('source_formal_config', None)
    return payload


def _bundle_signature(exp: dict[str, Any]) -> str:
    raw = json.dumps(_bundle_invariant_payload(exp), sort_keys=True, separators=(',', ':'), ensure_ascii=False)
    return hashlib.sha256(raw.encode('utf-8')).hexdigest().upper()


def _render_rgb_only(stage06: Any, camera: Any) -> np.ndarray:
    try:
        render_out = camera.render(rgb=True, depth=False, segmentation=False, force_render=True)
    except TypeError:
        try:
            render_out = camera.render(rgb=True, depth=False, segmentation=False)
        except TypeError:
            render_out = camera.render()
    rgb = render_out[0] if isinstance(render_out, tuple) else render_out
    return _to_uint8_image(stage06, rgb)


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description='Render one gravity/collision experiment json.')
    parser.add_argument('--config', required=True, type=Path, help='primary physics/camera config json')
    parser.add_argument(
        '--extra-camera-config',
        action='append',
        default=[],
        type=Path,
        help='additional same-scene camera config; may be repeated',
    )
    return parser.parse_args()


def main() -> None:
    args = parse_args()
    config_path = args.config.resolve()
    exp = load_json(config_path)
    if not isinstance(exp, dict):
        raise ValueError('config must be a json object')
    exp = _load_background_profile(exp, config_path)

    extra_camera_experiments: list[dict[str, Any]] = []
    primary_bundle_signature = _bundle_signature(exp)
    for extra_path_arg in args.extra_camera_config:
        extra_path = extra_path_arg.resolve()
        extra_exp = load_json(extra_path)
        if not isinstance(extra_exp, dict):
            raise ValueError(f'extra camera config must be a json object: {extra_path}')
        extra_exp = _load_background_profile(extra_exp, extra_path)
        extra_signature = _bundle_signature(extra_exp)
        if extra_signature != primary_bundle_signature:
            raise ValueError(
                'multi-camera invariant mismatch: '
                f'primary={config_path} signature={primary_bundle_signature} '
                f'extra={extra_path} signature={extra_signature}'
            )
        extra_render = extra_exp.get('render', {}) if isinstance(extra_exp.get('render'), dict) else {}
        if bool(extra_render.get('runtime_camera_updates', False)):
            raise ValueError('multi-camera production bundle requires fixed camera poses')
        extra_camera_experiments.append(
            {
                'config_path': extra_path,
                'exp': extra_exp,
                'render_cfg': extra_render,
                'ann_cfg': extra_exp.get('annotations', {}) if isinstance(extra_exp.get('annotations'), dict) else {},
                'camera_id': str(extra_exp.get('camera_id', extra_path.stem)),
            }
        )
    if extra_camera_experiments:
        log_info(
            f'[MULTICAM] validated same-scene bundle cameras='
            f'{1 + len(extra_camera_experiments)} signature={primary_bundle_signature}'
        )

    replay_path_raw = exp.get('trajectory_replay_path')
    replay_path: Path | None = None
    replay_frames: list[dict[str, Any]] | None = None
    replay_sha256: str | None = None
    if isinstance(replay_path_raw, str) and replay_path_raw.strip():
        replay_path = _resolve_input_path(replay_path_raw, config_path=config_path)
        replay_raw = replay_path.read_bytes()
        replay_data = json.loads(replay_raw.decode('utf-8'))
        replay_rows = replay_data.get('frames') if isinstance(replay_data, dict) else None
        if not isinstance(replay_rows, list) or not all(isinstance(row, dict) for row in replay_rows):
            raise ValueError(f'trajectory replay lacks frame rows: {replay_path}')
        replay_frames = replay_rows
        replay_sha256 = hashlib.sha256(replay_raw).hexdigest().upper()
        expected_sha256 = str(exp.get('trajectory_replay_sha256', '')).strip().upper()
        if expected_sha256 and replay_sha256 != expected_sha256:
            raise ValueError(f'trajectory replay sha256 mismatch: expected={expected_sha256} actual={replay_sha256}')
        log_info(f'trajectory replay loaded: {replay_path} frames={len(replay_frames)} sha256={replay_sha256}')

    manifest_path = _resolve_input_path(exp['manifest'], config_path=config_path)
    manifest = load_json(manifest_path)
    if not isinstance(manifest, dict):
        raise ValueError('manifest must be a json object')
    manifest = _translate_background_manifest(manifest, exp.get('_background_anchor'))

    scene_cfg = exp.get('scene_overrides', {}) if isinstance(exp.get('scene_overrides'), dict) else {}
    render_cfg = exp.get('render', {}) if isinstance(exp.get('render'), dict) else {}
    ann_cfg = exp.get('annotations', {}) if isinstance(exp.get('annotations'), dict) else {}
    placement_cfg = exp.get('placement', {}) if isinstance(exp.get('placement'), dict) else {}
    dynamic_specs = exp.get('dynamic_objects', []) if isinstance(exp.get('dynamic_objects'), list) else []
    show_viewer = bool(exp.get('show_viewer', False))
    use_full_scene = bool(exp.get('use_full_scene', False))

    stage06 = _load_stage06()
    stage09 = _load_stage09()

    adjusted_objects, placement_debug, layout_mesh = _load_and_adjust_static_objects(manifest, {
        'skip_placement': bool(exp.get('skip_placement', False)),
        **placement_cfg,
    })

    raw_seed = exp.get('random_seed')
    random_seed = (int(raw_seed) & 0x7FFFFFFF) if raw_seed is not None else None
    if random_seed is not None:
        np.random.seed(random_seed)
    import quadrants as _qd, functools as _ft
    _qd.init=_ft.partial(_qd.init,cpu_max_num_threads=1)
    stage06.gs.init(backend=stage06.gs.cpu,seed=random_seed,precision='64')
    assert _qd.lang.impl.current_cfg().cpu_max_num_threads==1
    log_info(f'physics random_seed applied = {random_seed} raw_config_seed={raw_seed}')
    scene = _build_scene_with_overrides(stage06, show_viewer=show_viewer, scene_cfg=scene_cfg)
    prebuild_gravity_applied = _apply_scene_gravity(scene, scene_cfg.get('gravity'))
    static_entities = _add_static_scene(stage06, scene, manifest, adjusted_objects, layout_mesh, use_full_scene, scene_cfg)
    room_bounds = _room_bounds_from_context(manifest, placement_debug, layout_mesh if isinstance(layout_mesh, str) else None, scene_cfg)
    wall_specs = _room_wall_collider_specs(room_bounds, scene_cfg)
    wall_entries = _add_dynamic_objects(stage06, scene, wall_specs) if wall_specs else []
    if wall_specs:
        log_info(f'Added room wall colliders: count={len(wall_specs)} bounds={room_bounds}')
    elif scene_cfg.get('room_wall_colliders', True):
        log_warn('room_wall_colliders requested but room bounds could not be resolved.')
    dynamic_entries = wall_entries + _add_dynamic_objects(stage06, scene, dynamic_specs)
    if not dynamic_entries:
        raise ValueError('dynamic_objects is empty; this gravity/collision pipeline expects at least one dynamic object')

    camera_mode = str(render_cfg.get('camera_mode', 'focus_dynamic')).lower()
    center, extent = _estimate_orbit_center(stage09, placement_debug, layout_mesh if isinstance(layout_mesh, str) else None, dynamic_entries)
    camera, camera_init_debug = _add_camera_with_render_overrides(
        stage06,
        scene,
        manifest,
        render_cfg,
        camera_mode,
        center,
        dynamic_entries,
    )
    for state in extra_camera_experiments:
        extra_render_cfg = state['render_cfg']
        extra_camera_mode = str(extra_render_cfg.get('camera_mode', 'focus_dynamic')).lower()
        extra_camera, extra_camera_debug = _add_camera_with_render_overrides(
            stage06,
            scene,
            manifest,
            extra_render_cfg,
            extra_camera_mode,
            center,
            dynamic_entries,
        )
        state['camera'] = extra_camera
        state['camera_mode'] = extra_camera_mode
        state['camera_debug'] = extra_camera_debug
    scene.build()
    _internal_context={'active':False,'step':None,'index':0}
    _original_substep=scene.sim.rigid_solver.substep
    def _complete_contact_substep(_f):
        _original_substep(_f)
        if not _internal_context['active']:return
        _rows=_read_scene_contacts(scene,geom_name_map,_internal_context['step'])
        for _row in _rows:
            _pair=tuple(sorted((_row['entity_a'],_row['entity_b'])))
            _stamp=(_internal_context['step'],_internal_context['index'])
            _previous=_frame_contact_accumulator.get(_pair)
            if _previous is None:
                _previous=dict(_row,physics_step_index=_stamp[0],physics_substep_index=_stamp[1],max_penetration_physics_step_index=_stamp[0],max_penetration_internal_substep_index=_stamp[1],telemetry_scope='every_internal_substep_aggregate',native_contact_samples=1)
                _frame_contact_accumulator[_pair]=_previous
            else:
                _previous['native_contact_samples']+=1
                if _row['penetration_m']>_previous['penetration_m']:
                    _previous.update(penetration_m=_row['penetration_m'],max_penetration_physics_step_index=_stamp[0],max_penetration_internal_substep_index=_stamp[1])
        _internal_context['index']+=1
    scene.sim.rigid_solver.substep=_complete_contact_substep

    assert scene._para_level == 0
    primitive_orientation_qa = _verify_initial_primitive_orientations(stage06, dynamic_entries)
    postbuild_gravity_applied = _apply_scene_gravity(scene, scene_cfg.get('gravity'))
    runtime_gravity = _read_scene_gravity(scene)
    _reapply_dynamic_object_properties(dynamic_entries)
    _sync_v7_visual_proxies(dynamic_entries)
    _apply_static_object_overrides(static_entities, exp.get('static_object_overrides'))
    settle_steps = 0 if replay_frames is not None else max(0, int(scene_cfg.get('settle_steps', render_cfg.get('settle_steps', 8))))
    for _ in range(settle_steps):
        scene.step()
        _sync_v7_visual_proxies(dynamic_entries)

    frames = max(1, int(render_cfg.get('frames', 180)))
    if replay_frames is not None and len(replay_frames) != frames:
        raise ValueError(f'trajectory replay frame count mismatch: replay={len(replay_frames)} render={frames}')
    fps = max(1, int(render_cfg.get('fps', 30)))
    pre_static_frames = max(0, min(frames - 1, int(render_cfg.get('pre_static_frames', exp.get('pre_static_frames', 0)))))
    sim_dt = float(scene_cfg.get('dt', scene_cfg.get('sim_dt', 0.01)))
    physics_steps_per_render_frame = max(
        1,
        int(render_cfg.get('physics_steps_per_render_frame', scene_cfg.get('physics_steps_per_render_frame', 1))),
    )
    video_seconds = float(frames) / float(fps)
    static_hold_seconds = float(pre_static_frames) / float(fps)
    active_sim_seconds = float(max(0, frames - pre_static_frames) * physics_steps_per_render_frame) * sim_dt
    physical_timeline_seconds = static_hold_seconds + active_sim_seconds
    total_sim_seconds_including_static = float(frames * physics_steps_per_render_frame) * sim_dt
    runtime_camera_updates = bool(render_cfg.get('runtime_camera_updates', False))

    camera_fov_deg = render_cfg.get('camera_fov_deg')
    fixed_view_cfg = render_cfg.get('fixed_view', {})
    if camera_fov_deg is None and camera_mode == 'fixed_view' and isinstance(fixed_view_cfg, dict):
        camera_fov_deg = fixed_view_cfg.get('fov_deg')
    if camera_fov_deg is not None:
        for name in ('set_fov', 'set_camera_fov'):
            if hasattr(camera, name):
                try:
                    getattr(camera, name)(float(camera_fov_deg))
                    break
                except Exception:
                    continue

    save_video = safe_makedirs(Path(str(render_cfg['save_video'])))
    save_first_rgb = render_cfg.get('save_first_rgb')
    save_last_rgb = render_cfg.get('save_last_rgb')
    save_rgb_frames = bool(render_cfg.get('save_rgb_frames', False))
    save_depth_frames = bool(render_cfg.get('save_depth_frames', False))
    save_seg_frames = bool(render_cfg.get('save_seg_frames', False))
    requested_render_backend = str(render_cfg.get('render_backend', 'raster')).strip().lower()
    renderer_effective = requested_render_backend
    if requested_render_backend in ('raytracing', 'raytracer') and bool(scene_cfg.get('raytracing', scene_cfg.get('use_raytracing', False))):
        # The scene already owns a Genesis RayTracer renderer. Camera capture
        # still uses the standard RGB path; this is not a Raster downgrade.
        render_backend = 'raster'
        renderer_effective = 'genesis_raytracer'
        log_info('RayTracer scene uses the standard camera RGB capture path.')
    else:
        render_backend = requested_render_backend
    if render_backend not in ('raster', 'overlay_2d'):
        log_warn(f'Unknown render_backend={render_backend}, fallback to raster')
        render_backend = 'raster'
        renderer_effective = 'raster'

    if ann_cfg.get('enabled', True):
        annotations: dict[str, Any] = {
            'experiment': exp.get('experiment', {}),
            'manifest': str(manifest_path),
            'render': render_cfg,
            'scene_overrides': scene_cfg,
            'room_boundary': {
                'bounds': room_bounds,
                'wall_collider_count': len(wall_specs),
                'wall_colliders': [w.get('name') for w in wall_specs],
                'safety_enabled': scene_cfg.get('room_boundary_safety', True),
            },
            'time_diagnostic': {
                'sim_dt': sim_dt,
                'physics_steps_per_render_frame': physics_steps_per_render_frame,
                'render_fps': fps,
                'video_fps': fps,
                'frame_count': frames,
                'pre_static_frames': pre_static_frames,
                'active_simulated_seconds': active_sim_seconds,
                'static_hold_seconds': static_hold_seconds,
                'physical_timeline_seconds': physical_timeline_seconds,
                'total_simulated_seconds_if_static_stepped': total_sim_seconds_including_static,
                'video_seconds': video_seconds,
            },
            'frames': [],
            'dynamic_objects': [
                {
                    'name': x['name'],
                    'spec': x['spec'],
                }
                for x in dynamic_entries
            ],
        }
    else:
        annotations = {}

    if annotations and replay_frames is not None:
        annotations['trajectory_replay'] = {
            'path': str(replay_path),
            'sha256': replay_sha256,
            'frame_count': len(replay_frames),
            'physics_source_preserved': True,
        }

    runtime_forces = _parse_runtime_forces(exp, dynamic_entries, frames)
    if runtime_forces:
        for rf in runtime_forces:
            log_info(
                f'runtime_force configured: name={rf["name"]} target={rf["target"]} '
                f'force_world={_fmt_vec3(rf["force"])} frame_range=[{rf["frame_start"]}, {rf["frame_end"]}]'
            )
        if annotations:
            annotations['runtime_forces'] = [
                {
                    'name': rf['name'],
                    'target': rf['target'],
                    'force_world': [float(rf['force'][0]), float(rf['force'][1]), float(rf['force'][2])],
                    'frame_start': int(rf['frame_start']),
                    'frame_end': int(rf['frame_end']),
                }
                for rf in runtime_forces
            ]
    else:
        log_info('runtime_force configured: <none>')

    exp_meta = exp.get('experiment', {}) if isinstance(exp.get('experiment'), dict) else {}
    drop_name_from_meta = str(exp_meta.get('drop_object_name', '')).strip()
    target_name_from_meta = str(exp_meta.get('target_object_name', '')).strip()
    drop_name_candidates = [
        'tabletop_domino_ball',
        'tabletop_projectile_ball',
        'tabletop_blocks_ball',
        'tabletop_rolling_ball',
        'drop_ball',
        drop_name_from_meta,
        'tilted_drop_box',
        'drop_box',
    ]
    target_name_candidates = [
        target_name_from_meta,
        'target_box_on_table',
        'target_box',
        'impact_box',
    ]
    drop_entry = _first_entry_any(dynamic_entries, drop_name_candidates)
    if drop_entry is None:
        for _entry in dynamic_entries:
            if 'ball' in str(_entry.get('name', '')).lower():
                drop_entry = _entry
                break
    target_entry = _first_entry_any(dynamic_entries, target_name_candidates)
    drop_name = str(drop_entry.get('name', '<none>')) if drop_entry is not None else '<none>'
    target_name = str(target_entry.get('name', '<none>')) if target_entry is not None else '<none>'

    expected_impact = exp_meta.get('expected_impact_point_world', exp_meta.get('target_corner_world'))
    if not (isinstance(expected_impact, (list, tuple)) and len(expected_impact) >= 3):
        expected_impact = None
    else:
        expected_impact = [float(expected_impact[0]), float(expected_impact[1]), float(expected_impact[2])]

    drop_radius = None
    drop_size = None
    target_size = None
    if drop_entry is not None:
        drop_spec = drop_entry.get('spec', {})
        if isinstance(drop_spec, dict):
            if 'radius' in drop_spec:
                try:
                    drop_radius = float(drop_spec.get('radius'))
                except Exception:
                    drop_radius = None
            if isinstance(drop_spec.get('size'), (list, tuple)) and len(drop_spec.get('size')) >= 3:
                drop_size = [
                    float(drop_spec['size'][0]),
                    float(drop_spec['size'][1]),
                    float(drop_spec['size'][2]),
                ]
            pose = drop_spec.get('pose', {}) if isinstance(drop_spec.get('pose'), dict) else {}
            drop_euler = pose.get('euler_xyz')
            drop_quat = pose.get('quaternion_xyzw')
        else:
            pose = {}
            drop_euler = None
            drop_quat = None
        log_info(f'{drop_name} initial_position={_fmt_vec3(drop_entry["initial_position"])}')
        if isinstance(drop_size, list) and len(drop_size) >= 3:
            log_info(f'{drop_name} size={_fmt_vec3(drop_size)}')
        if isinstance(drop_euler, (list, tuple)) and len(drop_euler) >= 3:
            log_info(f'{drop_name} initial_euler={_fmt_vec3(drop_euler)}')
        if isinstance(drop_quat, (list, tuple)) and len(drop_quat) >= 4:
            log_info(f'{drop_name} initial_quat_xyzw={[round(float(x), 5) for x in drop_quat[:4]]}')
    if target_entry is not None:
        target_spec = target_entry.get('spec', {})
        target_size = target_spec.get('size') if isinstance(target_spec, dict) else None
        log_info(f'{target_name} initial_position={_fmt_vec3(target_entry["initial_position"])}')
        if isinstance(target_size, (list, tuple)) and len(target_size) >= 3:
            log_info(f'{target_name} size={_fmt_vec3(target_size)}')
    if expected_impact is not None:
        log_info(f'expected impact point(world)={_fmt_vec3(expected_impact)}')

    fixed_view_cfg = render_cfg.get('fixed_view', {})
    if camera_mode == 'fixed_view' and isinstance(fixed_view_cfg, dict):
        cam_pos = _to_vec3(fixed_view_cfg.get('position'), (2.6, -2.4, 1.9))
        cam_look = _to_vec3(fixed_view_cfg.get('look_at'), (0.0, 0.0, 0.8))
        log_info(f'camera fixed_view pos={_fmt_vec3(cam_pos)} look_at={_fmt_vec3(cam_look)} fov={camera_fov_deg if camera_fov_deg is not None else fixed_view_cfg.get("fov_deg", "<default>")}')
    elif camera_mode in ('impact_follow', 'impact_track'):
        impact_offset = _to_vec3(render_cfg.get('impact_offset'), (1.15, -0.95, 0.95))
        impact_lookat_offset = _to_vec3(render_cfg.get('impact_lookat_offset'), (0.0, 0.0, 0.08))
        log_info(f'camera impact_follow offset={_fmt_vec3(impact_offset)} lookat_offset={_fmt_vec3(impact_lookat_offset)} fov={camera_fov_deg if camera_fov_deg is not None else "<default>"}')
    elif camera_mode in ('focus_dynamic', 'focus_collision', 'closeup'):
        focus_offset = _to_vec3(render_cfg.get('focus_offset'), (2.6, -2.4, 1.9))
        focus_lookat_offset = _to_vec3(render_cfg.get('focus_lookat_offset'), (0.0, 0.0, 0.35))
        log_info(f'camera {camera_mode} offset={_fmt_vec3(focus_offset)} lookat_offset={_fmt_vec3(focus_lookat_offset)} fov={camera_fov_deg if camera_fov_deg is not None else "<default>"}')

    log_info(f'gravity override (cfg) = {scene_cfg.get("gravity", "<default>")}')
    log_info(f'gravity apply prebuild={prebuild_gravity_applied} postbuild={postbuild_gravity_applied} runtime={runtime_gravity}')
    log_info(f'camera init resolved = {camera_init_debug}')
    log_info(f'runtime camera updates enabled = {runtime_camera_updates}')
    log_info(f'output video path = {save_video}')
    log_info(f'render backend effective = {renderer_effective}; capture path = {render_backend}')
    log_info(f'pre_static_frames = {pre_static_frames}')
    log_info(
        'time diagnostic: '
        f'sim_dt={sim_dt:.8f} physics_steps_per_render_frame={physics_steps_per_render_frame} '
        f'fps={fps} frames={frames} active_sim_seconds={active_sim_seconds:.4f} '
        f'static_hold_seconds={static_hold_seconds:.4f} physical_timeline_seconds={physical_timeline_seconds:.4f} '
        f'video_seconds={video_seconds:.4f}'
    )
    table_collider_entry = None
    for _entry in dynamic_entries:
        if bool((_entry.get('spec') or {}).get('is_tabletop_collision_slab')):
            table_collider_entry = _entry
            break
    table_debug_cfg = scene_cfg.get('table_collision', exp.get('table_collision', {})) if isinstance(exp, dict) else {}
    if table_collider_entry is not None:
        spec = table_collider_entry.get('spec', {})
        pose = spec.get('pose', {}) if isinstance(spec.get('pose'), dict) else {}
        size = spec.get('size', [0.0, 0.0, 0.0])
        pos = pose.get('position', [0.0, 0.0, 0.0])
        min_z = float(pos[2]) - 0.5 * float(size[2])
        max_z = float(pos[2]) + 0.5 * float(size[2])
        log_info(f'[PHYSICS_DEBUG] table_top_z = {float(table_debug_cfg.get("table_top_z", max_z)):.4f}')
        log_info(f'[PHYSICS_DEBUG] table_collider_min_z = {min_z:.4f}')
        log_info(f'[PHYSICS_DEBUG] table_collider_max_z = {max_z:.4f}')
    if drop_entry is not None:
        spec = drop_entry.get('spec', {})
        log_info(f'[PHYSICS_DEBUG] ball_radius = {float(spec.get("radius", drop_radius or 0.0)):.4f}')
        log_info(f'[PHYSICS_DEBUG] ball_initial_z = {float(drop_entry["initial_position"][2]):.4f}')
        log_info(f'[PHYSICS_DEBUG] ccd_enabled_for_ball = {bool(spec.get("ccd_enabled", spec.get("enable_ccd", False)))}')

    write_video = bool(render_cfg.get('write_video', True))
    use_native_recording = write_video and bool(render_cfg.get('use_native_recording', False)) and render_backend == 'raster'
    recording_mode = 'disabled' if not write_video else ('genesis_native' if use_native_recording else 'opencv_mp4v')
    log_info(f'video recording mode = {recording_mode}')
    if use_native_recording:
        camera.start_recording()

    video_writer = None
    writer_failed = False
    first_rgb_saved = False
    first_rgb_for_motion: np.ndarray | None = None
    last_rgb_for_motion: np.ndarray | None = None
    drop_track: list[np.ndarray] = []
    target_track: list[np.ndarray] = []
    overlay_bg_rgb: np.ndarray | None = None
    overlay_trails: dict[str, list[tuple[int, int]]] = {}

    for state in extra_camera_experiments:
        extra_render_cfg = state['render_cfg']
        if str(extra_render_cfg.get('render_backend', requested_render_backend)).strip().lower() != requested_render_backend:
            raise ValueError('multi-camera bundle requires the same render backend for every camera')
        if int(extra_render_cfg.get('frames', frames)) != frames or int(extra_render_cfg.get('fps', fps)) != fps:
            raise ValueError('multi-camera bundle requires identical frame count and fps')
        if bool(extra_render_cfg.get('save_depth_frames', False)) or bool(extra_render_cfg.get('save_seg_frames', False)):
            raise ValueError('extra cameras in a multi-camera bundle cannot request depth or segmentation')
        if bool(extra_render_cfg.get('use_native_recording', False)):
            raise ValueError('multi-camera bundle requires OpenCV recording for extra cameras')
        state['write_video'] = bool(extra_render_cfg.get('write_video', True))
        state['save_video'] = safe_makedirs(Path(str(extra_render_cfg['save_video'])))
        state['save_first_rgb'] = extra_render_cfg.get('save_first_rgb')
        state['save_last_rgb'] = extra_render_cfg.get('save_last_rgb')
        state['video_writer'] = None
        state['first_rgb_saved'] = False
        state['first_rgb_for_motion'] = None
        state['last_rgb_for_motion'] = None
        log_info(
            f'[MULTICAM] camera={state["camera_id"]} output={state["save_video"]} '
            f'pose={state["camera_debug"]}'
        )

    cam_pos_dbg = np.asarray(camera_init_debug.get('position', [0.0, 0.0, 1.0]), dtype=float).reshape(-1)[:3]
    cam_look_dbg = np.asarray(camera_init_debug.get('look_at', [0.0, 0.0, 0.0]), dtype=float).reshape(-1)[:3]
    cam_fov_dbg = float(camera_init_debug.get('fov', camera_fov_deg if camera_fov_deg is not None else 60.0))
    cam_res_dbg = camera_init_debug.get('res', [1280, 720])
    if isinstance(cam_res_dbg, (list, tuple)) and len(cam_res_dbg) >= 2:
        frame_w = int(cam_res_dbg[0])
        frame_h = int(cam_res_dbg[1])
        aspect = float(frame_w) / max(float(frame_h), 1.0)
    else:
        frame_w = 1280
        frame_h = 720
        aspect = 16.0 / 9.0
    cam_right_dbg, cam_up_dbg, cam_fwd_dbg = _camera_basis(
        cam_pos_dbg,
        cam_look_dbg,
        np.asarray([0.0, 0.0, 1.0], dtype=float),
    )

    if render_backend == 'overlay_2d':
        if cv2 is None:
            raise RuntimeError('render_backend=overlay_2d requires OpenCV.')
        bg_raw = render_cfg.get('overlay_background')
        if isinstance(bg_raw, str) and bg_raw.strip():
            bg_path = _resolve_input_path(bg_raw, config_path=config_path)
            if bg_path.exists():
                bg_bgr = cv2.imread(str(bg_path), cv2.IMREAD_COLOR)
                if bg_bgr is not None:
                    overlay_bg_rgb = np.ascontiguousarray(bg_bgr[..., ::-1])
                    log_info(f'overlay background loaded: {bg_path}')
                else:
                    log_warn(f'overlay background decode failed: {bg_path}')
            else:
                log_warn(f'overlay background not found: {bg_path}')
    gravity_z_dbg = None
    if runtime_gravity is not None:
        try:
            gravity_z_dbg = float(runtime_gravity[2])
        except Exception:
            gravity_z_dbg = None
    if gravity_z_dbg is None:
        gravity_cfg = scene_cfg.get('gravity')
        if isinstance(gravity_cfg, (list, tuple)) and len(gravity_cfg) >= 3:
            try:
                gravity_z_dbg = float(gravity_cfg[2])
            except Exception:
                gravity_z_dbg = None
    if gravity_z_dbg is None:
        gravity_z_dbg = -9.81
    boundary_safety_events_all: list[dict[str, Any]] = []
    record_contacts = bool(scene_cfg.get('record_contacts', True))
    geom_name_map = _build_geom_name_map(dynamic_entries) if record_contacts else {}
    if record_contacts:
        log_info(f'[CONTACT_QA] geometry ids mapped to actors: {len(geom_name_map)}')
    for i in range(frames):
        sim_i = i - pre_static_frames
        static_phase = sim_i < 0
        per_frame_objects = []
        replay_frame = replay_frames[i] if replay_frames is not None else None
        replay_by_name: dict[str, dict[str, Any]] = {}
        if replay_frame is not None:
            replay_by_name = {
                str(row.get('name')): row
                for row in replay_frame.get('objects', [])
                if isinstance(row, dict) and row.get('name')
            }
            for entry in dynamic_entries:
                source = replay_by_name.get(entry['name'])
                applied = {'type': 'trajectory_replay', 'manual_pose': source is not None}
                if source is not None:
                    pos = np.asarray(source.get('position', entry['initial_position']), dtype=float)
                    quat = np.asarray(source.get('quaternion_xyzw', [0.0, 0.0, 0.0, 1.0]), dtype=float)
                    if not _try_set_entity_pos(entry['entity'], pos):
                        raise RuntimeError(f'trajectory replay position setter failed: {entry["name"]}')
                    if not _try_set_entity_quat(entry['entity'], quat):
                        raise RuntimeError(f'trajectory replay quaternion setter failed: {entry["name"]}')
                    velocity = source.get('velocity')
                    if isinstance(velocity, (list, tuple)) and len(velocity) >= 3:
                        _try_set_velocity(entry['entity'], velocity)
                per_frame_objects.append({'name': entry['name'], **applied})
            _sync_v7_visual_proxies(dynamic_entries)
        else:
            for entry in dynamic_entries:
                if static_phase:
                    applied = {'type': 'pre_static_hold', 'manual_pose': False}
                else:
                    applied = _apply_motion_step(entry, sim_i)
                per_frame_objects.append({'name': entry['name'], **applied})

        frame_runtime_forces: list[dict[str, Any]] = []
        frame_boundary_events: list[dict[str, Any]] = []
        frame_contacts: list[dict[str, Any]] = copy.deepcopy(replay_frame.get('contacts', [])) if replay_frame is not None else []
        _frame_contact_accumulator={}
        if replay_frame is None and not static_phase:
            for rf in runtime_forces:
                if sim_i < rf['frame_start'] or sim_i > rf['frame_end']:
                    continue
                ok, method = _try_apply_force(rf['entity'], rf['force'])
                if ok:
                    rf['applied_frames'] += 1
                    if not rf['first_method']:
                        rf['first_method'] = method
                else:
                    rf['failed_frames'] += 1
                frame_runtime_forces.append(
                    {
                        'name': rf['name'],
                        'target': rf['target'],
                        'force_world': [float(rf['force'][0]), float(rf['force'][1]), float(rf['force'][2])],
                        'applied': bool(ok),
                        'method': method,
                    }
                )

            for _physics_step_idx in range(physics_steps_per_render_frame):
                fractional_frame = sim_i + (_physics_step_idx + 1) / physics_steps_per_render_frame
                for entry in dynamic_entries:
                    motion = entry.get('spec', {}).get('motion', {})
                    if isinstance(motion, dict) and str(motion.get('type', '')).lower() == 'scripted_translate':
                        _apply_motion_step(entry, fractional_frame)
                _internal_context.update(active=True,step=_physics_step_idx,index=0)
                scene.step()
                _internal_context['active']=False
                # Complete internal-substep observer replaces duplicate exterior samples.
                _sync_v7_visual_proxies(dynamic_entries)
                frame_boundary_events.extend(
                    _apply_wall_boundary_safety(dynamic_entries, room_bounds, scene_cfg, i, _physics_step_idx)
                )
            if frame_boundary_events:
                boundary_safety_events_all.extend(frame_boundary_events)
        if replay_frame is None:frame_contacts=list(_frame_contact_accumulator.values())
        drop_pos = None
        target_pos = None
        if drop_entry is not None:
            drop_pos = _read_entity_pos(drop_entry['entity'], drop_entry.get('last_position', drop_entry['initial_position']))
            drop_track.append(drop_pos.copy())
        if target_entry is not None:
            target_pos = _read_entity_pos(target_entry['entity'], target_entry.get('last_position', target_entry['initial_position']))
            target_track.append(target_pos.copy())
        if runtime_camera_updates and render_backend == 'raster':
            _update_camera_pose(camera, camera_mode, i, frames, dynamic_entries=dynamic_entries, scene_center=center, scene_extent=extent, render_cfg=render_cfg)

        depth = None
        seg = None
        if render_backend == 'overlay_2d':
            bsize = None
            if isinstance(target_size, (list, tuple)) and len(target_size) >= 3:
                bsize = (float(target_size[0]), float(target_size[1]), float(target_size[2]))
            rgb_uint8 = _render_overlay_rgb_frame(
                background_rgb=overlay_bg_rgb,
                width=frame_w,
                height=frame_h,
                frame_idx=i,
                total_frames=frames,
                gravity_z=gravity_z_dbg,
                ball_pos=drop_pos,
                box_pos=target_pos,
                ball_radius=drop_radius,
                box_size=bsize,
                target_corner=expected_impact,
                cam_pos=cam_pos_dbg,
                cam_right=cam_right_dbg,
                cam_up=cam_up_dbg,
                cam_fwd=cam_fwd_dbg,
                cam_fov=cam_fov_dbg,
                trails=overlay_trails,
            )
        else:
            need_depth = save_depth_frames
            need_seg = save_seg_frames
            try:
                render_out = camera.render(rgb=True, depth=need_depth, segmentation=need_seg, force_render=True)
            except TypeError:
                try:
                    render_out = camera.render(rgb=True, depth=need_depth, segmentation=need_seg)
                except TypeError:
                    render_out = camera.render()

            rgb = None
            if isinstance(render_out, tuple):
                if len(render_out) >= 1:
                    rgb = render_out[0]
                if len(render_out) >= 2:
                    depth = render_out[1]
                if len(render_out) >= 3:
                    seg = render_out[2]
            else:
                rgb = render_out
            rgb_uint8 = _to_uint8_image(stage06, rgb)
        if write_video and not use_native_recording:
            if video_writer is None and not writer_failed:
                if cv2 is None:
                    writer_failed = True
                    raise RuntimeError('OpenCV unavailable and use_native_recording is False.')
                h, w = int(rgb_uint8.shape[0]), int(rgb_uint8.shape[1])
                video_writer = cv2.VideoWriter(str(save_video), cv2.VideoWriter_fourcc(*'mp4v'), float(fps), (w, h))
                if not video_writer.isOpened():
                    writer_failed = True
                    raise RuntimeError(f'Failed to open cv2.VideoWriter for {save_video}')
            if video_writer is not None:
                video_writer.write(rgb_uint8[..., ::-1])
        if first_rgb_for_motion is None:
            first_rgb_for_motion = rgb_uint8.copy()
        last_rgb_for_motion = rgb_uint8
        if save_first_rgb and not first_rgb_saved:
            first_path = safe_makedirs(Path(str(save_first_rgb)))
            Image.fromarray(rgb_uint8).save(first_path)
            first_rgb_saved = True

        if save_rgb_frames:
            frame_dir = Path(str(render_cfg.get('save_rgb_frames_dir', save_video.with_suffix('') / 'rgb')))
            frame_path = safe_makedirs(frame_dir / f'{i:06d}.png')
            Image.fromarray(rgb_uint8).save(frame_path)
        if save_depth_frames and depth is not None:
            depth_dir = Path(str(render_cfg.get('save_depth_dir', save_video.with_suffix('') / 'depth')))
            _save_depth_png(depth, depth_dir / f'{i:06d}.png')
        if save_seg_frames and seg is not None:
            seg_dir = Path(str(render_cfg.get('save_seg_dir', save_video.with_suffix('') / 'seg')))
            _save_seg_png(seg, seg_dir / f'{i:06d}.png')

        for state in extra_camera_experiments:
            if bool(state['render_cfg'].get('runtime_camera_updates', False)):
                _update_camera_pose(
                    state['camera'],
                    state['camera_mode'],
                    i,
                    frames,
                    dynamic_entries=dynamic_entries,
                    scene_center=center,
                    scene_extent=extent,
                    render_cfg=state['render_cfg'],
                )
            extra_rgb = _render_rgb_only(stage06, state['camera'])
            if state['write_video']:
                extra_writer = state['video_writer']
                if extra_writer is None:
                    if cv2 is None:
                        raise RuntimeError('OpenCV unavailable for multi-camera recording')
                    extra_h, extra_w = int(extra_rgb.shape[0]), int(extra_rgb.shape[1])
                    extra_writer = cv2.VideoWriter(
                        str(state['save_video']),
                        cv2.VideoWriter_fourcc(*'mp4v'),
                        float(fps),
                        (extra_w, extra_h),
                    )
                    if not extra_writer.isOpened():
                        raise RuntimeError(f'Failed to open cv2.VideoWriter for {state["save_video"]}')
                    state['video_writer'] = extra_writer
                extra_writer.write(extra_rgb[..., ::-1])
            if state['first_rgb_for_motion'] is None:
                state['first_rgb_for_motion'] = extra_rgb.copy()
            state['last_rgb_for_motion'] = extra_rgb
            if state['save_first_rgb'] and not state['first_rgb_saved']:
                extra_first_path = safe_makedirs(Path(str(state['save_first_rgb'])))
                Image.fromarray(extra_rgb).save(extra_first_path)
                state['first_rgb_saved'] = True

        if annotations:
            frame_ann = {
                'frame_index': i,
                'objects': [],
            }
            if frame_runtime_forces:
                frame_ann['runtime_forces'] = frame_runtime_forces
            if frame_boundary_events:
                frame_ann['wall_boundary_safety_events'] = frame_boundary_events
            if frame_contacts:
                frame_ann['contacts'] = frame_contacts
            for entry, applied in zip(dynamic_entries, per_frame_objects):
                source = replay_by_name.get(entry['name']) if replay_frame is not None else None
                pos = np.asarray(source['position'], dtype=float) if source is not None else _read_entity_pos(entry['entity'], entry.get('last_position', entry['initial_position']))
                vel = np.asarray(source['velocity'], dtype=float) if source is not None and source.get('velocity') is not None else _read_entity_vel(entry['entity'])
                quat = np.asarray(source['quaternion_xyzw'], dtype=float) if source is not None and source.get('quaternion_xyzw') is not None else _read_entity_quat(entry['entity'])
                ang_vel = np.asarray(source['angular_velocity'], dtype=float) if source is not None and source.get('angular_velocity') is not None else _read_entity_ang_vel(entry['entity'])
                frame_ann['objects'].append(
                    {
                        'name': entry['name'],
                        'position': [float(pos[0]), float(pos[1]), float(pos[2])],
                        'velocity': [float(vel[0]), float(vel[1]), float(vel[2])] if vel is not None else None,
                        'quaternion_xyzw': [float(quat[0]), float(quat[1]), float(quat[2]), float(quat[3])] if quat is not None else None,
                        'angular_velocity': [float(ang_vel[0]), float(ang_vel[1]), float(ang_vel[2])] if ang_vel is not None else None,
                        'motion': applied,
                    }
                )
            annotations['frames'].append(frame_ann)

        if (i + 1) % max(1, frames // 8) == 0 or i == frames - 1:
            focus = _get_dynamic_focus_center(dynamic_entries)
            focus_s = 'None' if focus is None else [round(float(x), 3) for x in focus.tolist()]
            drop_z = None
            target_z = None
            if drop_pos is not None:
                drop_z = round(float(drop_pos[2]), 3)
            if target_pos is not None:
                target_z = round(float(target_pos[2]), 3)
            rf_s = ''
            if runtime_forces:
                parts = []
                for rf in runtime_forces:
                    if rf['frame_start'] <= i <= rf['frame_end']:
                        parts.append(f'{rf["target"]}:{_fmt_vec3(rf["force"])}N')
                if parts:
                    rf_s = f' | runtime_force={"; ".join(parts)}'
            log_info(f'rendering progress: {i + 1}/{frames} | focus={focus_s} | {drop_name}_z={drop_z} {target_name}_z={target_z}{rf_s}')

    if use_native_recording:
        camera.stop_recording(save_to_filename=str(save_video), fps=fps)
        log_ok(f'Saved video: {save_video}')
    elif write_video:
        if video_writer is None:
            raise RuntimeError(f'No frame was written to video: {save_video}')
        video_writer.release()
        log_ok(f'Saved video (cv2): {save_video}')

    if first_rgb_for_motion is not None and last_rgb_for_motion is not None:
        motion_signal = float(np.mean(np.abs(last_rgb_for_motion.astype(np.float32) - first_rgb_for_motion.astype(np.float32))))
        log_info(f'motion signal (first vs last RGB mean abs diff) = {motion_signal:.4f}')
        if motion_signal < 0.35:
            log_warn('Very low motion signal in rendered video. Check camera framing / object visibility.')
        if save_last_rgb:
            last_path = safe_makedirs(Path(str(save_last_rgb)))
            Image.fromarray(last_rgb_for_motion).save(last_path)
            log_ok(f'Saved last RGB preview: {last_path}')

    for state in extra_camera_experiments:
        extra_writer = state['video_writer']
        if state['write_video']:
            if extra_writer is None:
                raise RuntimeError(f'No frame was written to multi-camera video: {state["save_video"]}')
            extra_writer.release()
            log_ok(f'[MULTICAM] Saved video (cv2): {state["save_video"]}')
        extra_first = state['first_rgb_for_motion']
        extra_last = state['last_rgb_for_motion']
        if extra_first is not None and extra_last is not None:
            extra_motion_signal = float(
                np.mean(np.abs(extra_last.astype(np.float32) - extra_first.astype(np.float32)))
            )
            log_info(
                f'[MULTICAM] camera={state["camera_id"]} '
                f'motion_signal={extra_motion_signal:.4f}'
            )
            if state['save_last_rgb']:
                extra_last_path = safe_makedirs(Path(str(state['save_last_rgb'])))
                Image.fromarray(extra_last).save(extra_last_path)
                log_ok(f'[MULTICAM] Saved last RGB preview: {extra_last_path}')

    if drop_track:
        drop_arr = np.stack(drop_track, axis=0)
        drop_disp = float(np.linalg.norm(drop_arr[-1] - drop_arr[0]))
        log_info(f'{drop_name} trajectory summary: start={_fmt_vec3(drop_arr[0])} end={_fmt_vec3(drop_arr[-1])} displacement={drop_disp:.4f}')
    else:
        drop_arr = None

    if target_track:
        target_arr = np.stack(target_track, axis=0)
        target_disp = float(np.linalg.norm(target_arr[-1] - target_arr[0]))
        log_info(f'{target_name} trajectory summary: start={_fmt_vec3(target_arr[0])} end={_fmt_vec3(target_arr[-1])} displacement={target_disp:.4f}')
    else:
        target_arr = None

    if drop_track:
        drop_vis_ratio = _visible_ratio(drop_track, cam_pos_dbg, cam_look_dbg, cam_fov_dbg, aspect)
        log_info(f'camera visibility estimate: {drop_name} in-view ratio={drop_vis_ratio:.3f}')
    if target_track:
        target_vis_ratio = _visible_ratio(target_track, cam_pos_dbg, cam_look_dbg, cam_fov_dbg, aspect)
        log_info(f'camera visibility estimate: {target_name} in-view ratio={target_vis_ratio:.3f}')

    for rf in runtime_forces:
        active_frames = max(0, int(rf['frame_end']) - int(rf['frame_start']) + 1)
        log_info(
            f'runtime_force summary: name={rf["name"]} target={rf["target"]} '
            f'force_world={_fmt_vec3(rf["force"])} active_frames={active_frames} '
            f'applied_frames={rf["applied_frames"]} failed_frames={rf["failed_frames"]} '
            f'first_method={rf["first_method"] if rf["first_method"] else "<none>"}'
        )
        if rf['applied_frames'] <= 0:
            log_warn(
                f'runtime_force appears inactive for target={rf["target"]}. '
                f'Check supported force APIs for this Genesis version.'
            )

    if expected_impact is not None and drop_arr is not None:
        impact = np.asarray(expected_impact, dtype=float).reshape(3)
        dist = np.linalg.norm(drop_arr - impact[None, :], axis=1)
        min_idx = int(np.argmin(dist))
        min_dist = float(dist[min_idx])
        if isinstance(drop_size, list) and len(drop_size) >= 3:
            thresh = max(0.06, 0.5 * min(float(drop_size[0]), float(drop_size[1])))
        else:
            radius_for_check = float(drop_radius) if drop_radius is not None else 0.09
            thresh = max(0.04, radius_for_check * 1.35)
        impact_hit = bool(min_dist <= thresh)
        log_info(f'impact check: min_{drop_name}_to_expected_impact_dist={min_dist:.4f} at_frame={min_idx} threshold={thresh:.4f} hit={impact_hit}')
        if target_arr is not None:
            lateral = float(np.linalg.norm(drop_arr[min_idx, :2] - target_arr[min_idx, :2]))
            log_info(f'impact frame lateral distance to {target_name} center={lateral:.4f}')

    trajectory_debug = {}
    if drop_track:
        arr = np.stack(drop_track, axis=0)
        sample_frames = {0.0: 0, 2.0: min(len(arr) - 1, int(round(2.0 * fps))), 4.0: min(len(arr) - 1, int(round(4.0 * fps))), 6.0: min(len(arr) - 1, int(round(6.0 * fps))), 8.0: min(len(arr) - 1, int(round(8.0 * fps)))}
        speeds = np.linalg.norm(np.diff(arr, axis=0), axis=1) * float(fps) if len(arr) > 1 else np.zeros(1)
        table_top_dbg = float((exp.get('table_collision') or {}).get('table_top_z', 0.8)) if isinstance(exp.get('table_collision'), dict) else 0.8
        ball_radius_dbg = float((drop_entry.get('spec', {}) if drop_entry else {}).get('radius', drop_radius or 0.05))
        ball_min_z = float(np.min(arr[:, 2]))
        ball_penetrated_table = bool(np.any((arr[:, 2] - ball_radius_dbg) < (table_top_dbg - 0.018)) and np.any(arr[:, 0] < float((exp.get('table_collision') or {}).get('table_max', [0,0,0])[0] if isinstance(exp.get('table_collision'), dict) else 4.48)))
        ball_fell_from_table = bool(arr[-1, 2] < table_top_dbg - 0.10 or np.max(arr[:, 0]) > float((exp.get('table_collision') or {}).get('table_max', [4.48,0,0])[0] if isinstance(exp.get('table_collision'), dict) else 4.48))
        trajectory_debug = {
            'ball_min_z_over_time': ball_min_z,
            'ball_speed_mean': float(np.mean(speeds)) if speeds.size else 0.0,
            'ball_speed_final': float(speeds[-1]) if speeds.size else 0.0,
            'ball_fell_from_table': ball_fell_from_table,
            'ball_penetrated_table': ball_penetrated_table,
            'contact_count_table_ball': None,
            'samples': {f't_{t:g}': [float(x) for x in arr[idx, :3]] for t, idx in sample_frames.items()},
        }
        for t, idx in sample_frames.items():
            log_info(f'[TRAJECTORY_DEBUG] t={t:.1f} ball_pos={_fmt_vec3(arr[idx])}')
        log_info(f'[TRAJECTORY_DEBUG] ball_speed_mean={trajectory_debug["ball_speed_mean"]:.4f}')
        log_info(f'[TRAJECTORY_DEBUG] ball_speed_final={trajectory_debug["ball_speed_final"]:.4f}')
        log_info(f'[TRAJECTORY_DEBUG] ball_fell_from_table={ball_fell_from_table}')
        log_info(f'[PHYSICS_DEBUG] ball_min_z_over_time = {ball_min_z:.4f}')
        log_info(f'[PHYSICS_DEBUG] contact_count_table_ball = <api_unavailable>')

    if annotations:
        annotations['camera_id'] = str(exp.get('camera_id', config_path.stem))
        annotations['camera_bundle'] = {
            'mode': 'same_scene_multicamera' if extra_camera_experiments else 'single_camera',
            'camera_count': 1 + len(extra_camera_experiments),
            'physics_simulation_count': 1,
            'bundle_signature': primary_bundle_signature,
        }
        annotations['wall_boundary_safety_summary'] = {
            'event_count': len(boundary_safety_events_all),
            'events': boundary_safety_events_all[:200],
        }
        annotations['trajectory_debug'] = trajectory_debug
        annotations['physics_debug'] = {
            'table_collision_added': table_collider_entry is not None,
            'ccd_enabled_for_ball': bool((drop_entry.get('spec', {}) if drop_entry else {}).get('ccd_enabled', False)),
            'table_collision': exp.get('table_collision'),
            'effective_entity_properties': _read_effective_entity_properties(dynamic_entries),
        }
        event_qa_cfg = exp.get('event_qa', {}) if isinstance(exp.get('event_qa'), dict) else {}
        if event_qa_cfg.get('type') == 't15_edge_fall':
            annotations['event_qa'] = classify_t15_result(annotations['frames'], event_qa_cfg)
            log_info(f'[T15_QA] result={annotations["event_qa"]["result"]} reason={annotations["event_qa"]["reason"]}')
        ann_path = safe_makedirs(Path(str(ann_cfg.get('save_path', save_video.with_suffix('.json')))))
        save_json(ann_path, annotations)
        log_ok(f'Saved annotations: {ann_path}')
        primary_annotation_raw = ann_path.read_bytes()
        primary_annotation_sha256 = hashlib.sha256(primary_annotation_raw).hexdigest().upper()
        for state in extra_camera_experiments:
            if not bool(state['ann_cfg'].get('enabled', True)):
                continue
            extra_annotations = copy.deepcopy(annotations)
            extra_annotations['camera_id'] = state['camera_id']
            extra_annotations['render'] = state['render_cfg']
            extra_annotations['trajectory_replay'] = {
                'path': str(ann_path),
                'sha256': primary_annotation_sha256,
                'frame_count': len(annotations.get('frames', [])),
                'physics_source_preserved': True,
                'mode': 'same_scene_multicamera',
            }
            extra_ann_path = safe_makedirs(
                Path(str(state['ann_cfg'].get('save_path', Path(state['save_video']).with_suffix('.json'))))
            )
            save_json(extra_ann_path, extra_annotations)
            log_ok(f'[MULTICAM] Saved annotations: {extra_ann_path}')


if __name__ == '__main__':
    main()
